package com.rsvc;

/** How the voice-activated gate picks its threshold; config key {@code voiceActivation}. */
public enum ActivationLevel {
    AUTO("Auto"),
    MANUAL("Manual");
    private final String label;

    ActivationLevel(String label) {
        this.label = label;
    }

    @Override
    public String toString() {
        return label;
    }
}

package com.rsvc;

import com.rsvc.audio.NoiseGate;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

import java.awt.event.KeyEvent;

@ConfigGroup(RsVcConfig.GROUP)
public interface RsVcConfig extends Config {
    String GROUP = "rsvc";
    // Owned relay; the dev helper can still explicitly select loopback.
    String HOSTED_RELAY = "wss://51.81.34.93/v1/voice";

    @ConfigItem(
            keyName = "speakingIndicators",
            name = "Speaking indicators",
            position = 9,
            description =
                    "Show a green bubble above players while their voice is active. When alone,"
                        + " reads mic levels locally under your voice-mode controls; sends no audio"
                        + " without a listener.")
    default boolean speakingIndicators() {
        return true;
    }

    @ConfigItem(
            keyName = "voiceMode",
            name = "Voice mode",
            position = 8,
            description =
                    "Push-to-talk requires the key. Voice-activated captures automatically while"
                        + " RuneLite is focused and a listener or local speaking indicator is"
                        + " available, and sends only sound above the voice activation level."
                        + " Mute stops capture. Changing mode keeps your connection and room.")
    default VoiceMode voiceMode() {
        return VoiceMode.PUSH_TO_TALK;
    }

    @ConfigItem(
            keyName = "pushToTalk",
            name = "Push-to-talk",
            position = 2,
            description =
                    "In push-to-talk mode, hold while RuneLite is focused to transmit to nearby"
                            + " listeners.")
    default Keybind pushToTalk() {
        return new Keybind(KeyEvent.VK_V, KeyEvent.CTRL_DOWN_MASK);
    }

    @ConfigItem(
            keyName = "muteHotkey",
            name = "Toggle mic mute",
            position = 10,
            description = "Toggle microphone mute while the game has focus. Works in either voice mode.")
    default Keybind muteHotkey() {
        return new Keybind(KeyEvent.VK_F8, 0);
    }

    @ConfigItem(
            keyName = "deafenHotkey",
            name = "Toggle deafen",
            position = 11,
            description = "Toggle incoming voice and microphone mute while the game has focus. Works in either voice mode.")
    default Keybind deafenHotkey() {
        return new Keybind(KeyEvent.VK_F9, 0);
    }

    @ConfigItem(
            keyName = "voiceActivation",
            name = "Voice activation level",
            position = 12,
            description =
                    "Voice-activated mode only. Auto learns your background noise and sends sound"
                        + " about 12 dB above it. Manual sends sound above the threshold below."
                        + " The sidebar meter shows your mic level and where it opens.")
    default ActivationLevel voiceActivation() {
        return ActivationLevel.AUTO;
    }

    @Range(min = NoiseGate.MIN_MANUAL_DB, max = NoiseGate.MAX_MANUAL_DB)
    @Units(" dB")
    @ConfigItem(
            keyName = "voiceActivationThreshold",
            name = "Manual threshold",
            position = 13,
            description =
                    "With Manual voice activation, sound quieter than this is not sent. Lower is"
                        + " more sensitive. Speech is usually -30 to -15 dB; hiss and fans -70 to"
                        + " -50 dB.")
    default int voiceActivationThreshold() {
        return NoiseGate.DEFAULT_MANUAL_DB;
    }

    @Range(min = 0, max = 100)
    @ConfigItem(
            keyName = "volume",
            name = "Voice volume",
            position = 3,
            description = "Playback volume, 0–100 percent")
    default int volume() {
        return 80;
    }

    @ConfigItem(
            keyName = "microphone",
            name = "Microphone",
            position = 4,
            hidden = true,
            description = "Selected in Devices. Blank means Default.")
    default String microphone() {
        return "";
    }

    @ConfigItem(
            keyName = "speakers",
            name = "Speakers",
            position = 5,
            hidden = true,
            description = "Selected in Devices. Blank means Default.")
    default String speakers() {
        return "";
    }
}

package com.rsvc;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.rsvc.audio.AudioEngine;
import com.rsvc.audio.NoiseGate;
import com.rsvc.network.DisconnectReason;
import com.rsvc.client.VoiceClient;
import com.rsvc.network.VoicePacket;
import com.rsvc.network.VoiceConnection;
import com.rsvc.party.PartyJoinRequest;
import com.rsvc.party.PartyVoice;
import com.rsvc.party.RsVcPartyVoice;
import com.rsvc.proximity.ProximityMatcher;
import com.rsvc.ui.AudioDevicePicker;
import com.rsvc.ui.CaptureFocus;
import com.rsvc.ui.SpeakingOverlay;
import com.rsvc.ui.VoicePanel;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.FocusChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.PlayerDespawned;
import net.runelite.api.events.PlayerSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.messages.UserSync;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

import okhttp3.OkHttpClient;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.event.KeyEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;

import javax.inject.Inject;
import javax.swing.SwingUtilities;

/** RuneLite lifecycle and game-thread coordination for voice, audio devices and the sidebar. */
@PluginDescriptor(
        name = "RS Voice Chat",
        internalName = "rs-vc",
        description = "Opt-in proximity voice within 20 tiles",
        tags = {"voice", "proximity", "audio"})
public class RsVcPlugin extends Plugin implements KeyListener {
    private static final Logger log = LoggerFactory.getLogger(RsVcPlugin.class);
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private RsVcConfig config;
    @Inject private Gson gson;
    @Inject private OkHttpClient http;
    @Inject private KeyManager keyManager;
    @Inject private ClientToolbar toolbar;
    @Inject private ConfigManager configManager;
    @Inject private OverlayManager overlayManager;
    @Inject private PartyService partyService;
    @Inject private WSClient partySocket;

    private final PartyVoice partyVoice = new PartyVoice();
    private final PartyJoinRequest partyJoin = new PartyJoinRequest();

    private VoicePanel panel;
    private VoiceObserver observer = VoiceObserver.NONE;
    private Runnable localTestCleanup;
    private BooleanSupplier localTestSpeaking;
    private SpeakingOverlay speakingOverlay;
    private volatile List<Player> speakingPlayers = Collections.emptyList();
    private final Map<Long, Player> matchedPlayers = new HashMap<>();
    private long nextSpeakingUpdate;
    private AudioDevicePicker devicePicker;
    private NavigationButton navigation;
    // These references/flags are also read by WebSocket and audio callbacks.
    private volatile AudioEngine audio;
    // Read on the capture thread before each packet, so setting changes apply immediately.
    private final NoiseGate.Settings gateSettings =
            new NoiseGate.Settings() {
                @Override
                public boolean enabled() {
                    return config.voiceMode() == VoiceMode.VOICE_ACTIVATED;
                }

                @Override
                public boolean auto() {
                    return config.voiceActivation() == ActivationLevel.AUTO;
                }

                @Override
                public int manualDb() {
                    return config.voiceActivationThreshold();
                }
            };
    private volatile boolean muted;
    private volatile boolean deaf;
    private volatile boolean held;
    private volatile boolean keyDown;
    private volatile boolean started;
    private volatile boolean focused;
    private volatile CaptureFocus captureFocus;
    // Game-thread-owned collections; workers receive copies rather than game objects.
    private final Set<Long> blocked = new HashSet<>();
    private final Set<String> mutedNames = new HashSet<>();
    private final Map<String, Integer> speakerVolumes = new HashMap<>();
    private List<VoiceConnection.Peer> peers = Collections.emptyList();
    private final java.util.concurrent.atomic.AtomicReference<Runnable> pendingRoster =
            new java.util.concurrent.atomic.AtomicReference<>();
    private final VoiceClient voice = new VoiceClient();
    private volatile boolean localTesting;

    private final Set<Player> visiblePlayers =
            Collections.newSetFromMap(new java.util.IdentityHashMap<>());
    private final ProximityMatcher matcher = new ProximityMatcher();
    private WorldView trackedView;
    private final HotkeyListener muteHotkey = new HotkeyListener(() -> config.muteHotkey()) {
        @Override
        public void hotkeyPressed() {
            clientThread.invokeLater(() -> setMicrophoneMuted(!muted));
        }
    };
    private final HotkeyListener deafenHotkey = new HotkeyListener(() -> config.deafenHotkey()) {
        @Override
        public void hotkeyPressed() {
            clientThread.invokeLater(() -> setDeafened(!deaf));
        }
    };

    @Provides
    RsVcConfig provideConfig(ConfigManager manager) {
        return manager.getConfig(RsVcConfig.class);
    }

    @Override
    protected void startUp() {
        partySocket.registerMessage(RsVcPartyVoice.class);
        muted = false;
        deaf = false;
        held = false;
        keyDown = false;
        voice.invalidateAudio();
        focused = client.getCanvas().isFocusOwner();
        devicePicker =
                new AudioDevicePicker(
                        (mic, output) ->
                                clientThread.invokeLater(
                                        () -> {
                                            if (!started) {
                                                return;
                                            }
                                            if (mic.equals(config.microphone())
                                                    && output.equals(config.speakers())) {
                                                return;
                                            }
                                            configManager.setConfiguration(
                                                    RsVcConfig.GROUP, "microphone", mic);
                                            configManager.setConfiguration(
                                                    RsVcConfig.GROUP, "speakers", output);
                                        }));
        started = true;
        voice.requestConnection();
        SwingUtilities.invokeLater(
                () -> {
                    if (!started) {
                        return;
                    }
                    captureFocus =
                            new CaptureFocus(
                                    client.getCanvas(),
                                    () -> {
                                        keyDown = false;
                                        release();
                                    });
                    panel =
                            new VoicePanel(
                                    () -> clientThread.invokeLater(this::join),
                                    () -> clientThread.invokeLater(() -> leave("Disconnected")),
                                    value ->
                                            clientThread.invokeLater(() -> setMicrophoneMuted(value)),
                                    value ->
                                            clientThread.invokeLater(() -> setDeafened(value)),
                                    (id, value) ->
                                            clientThread.invokeLater(
                                                    () -> {
                                                        for (VoiceConnection.Peer peer : peers) {
                                                            if (peer.id == id) {
                                                                if (value) {
                                                                    mutedNames.add(peer.name);
                                                                } else {
                                                                    mutedNames.remove(peer.name);
                                                                }
                                                            }
                                                        }
                                                        if (audio != null) {
                                                            audio.block(id);
                                                        }
                                                        updateListening();
                                                    }),
                                    (id, level) ->
                                            clientThread.invokeLater(
                                                    () -> {
                                                        for (VoiceConnection.Peer peer : peers) {
                                                            if (peer.id == id) {
                                                                speakerVolumes.put(
                                                                        peer.name, level);
                                                            }
                                                        }
                                                        updateListening();
                                                    }),
                                    () ->
                                            clientThread.invokeLater(
                                                    () -> {
                                                        mutedNames.clear();
                                                        blocked.clear();
                                                        speakerVolumes
                                                                .entrySet()
                                                                .removeIf(e -> e.getValue() == 0);
                                                        updateListening();
                                                        refreshPeers();
                                                    }),
                                    () ->
                                            devicePicker.show(
                                                    panel, config.microphone(), config.speakers()));
                    panel.micLevel(
                            () -> {
                                AudioEngine current = audio;
                                return current == null ? null : current.micLevel();
                            });
                    panel.roomActions(
                            (action, code) ->
                                    clientThread.invokeLater(
                                            () -> {
                                                if (voice.partySelected()) {
                                                    return;
                                                }
                                                VoiceConnection current = voice.connection();
                                                if (current == null || !current.roomsAvailable()) {
                                                    status("Connect and log in before using rooms");
                                                    return;
                                                }
                                                release();
                                                if (audio != null) {
                                                    audio.clearPlayback();
                                                }
                                                voice.requestRoom(action, code);
                                                panel.roomRecovery(voice.recoveryPaused());
                                            }));
                    panel.roomRecoveryActions(
                            () -> clientThread.invokeLater(() -> recoverRoom(true)),
                            () -> clientThread.invokeLater(() -> recoverRoom(false)));
                    panel.partyAction(() -> clientThread.invokeLater(this::togglePartyVoice));
                    BufferedImage icon = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
                    Graphics2D g = icon.createGraphics();
                    g.setColor(new Color(85, 200, 160));
                    g.fillRoundRect(9, 2, 6, 13, 5, 5);
                    g.drawArc(5, 6, 14, 13, 180, 180);
                    g.drawLine(12, 19, 12, 23);
                    g.dispose();
                    navigation =
                            NavigationButton.builder()
                                    .tooltip("RS Voice Chat")
                                    .icon(icon)
                                    .priority(8)
                                    .panel(panel)
                                    .build();
                    toolbar.addNavigation(navigation);
                    clientThread.invokeLater(
                            () -> {
                                if (started && voice.connectionWanted()) {
                                    join();
                                }
                            });
                });
        // Toggle keys take precedence over PTT if the user assigns the same key.
        keyManager.registerKeyListener(muteHotkey);
        keyManager.registerKeyListener(deafenHotkey);
        keyManager.registerKeyListener(this);
        speakingOverlay = new SpeakingOverlay(client, () -> speakingPlayers);
        overlayManager.add(speakingOverlay);
    }

    @Override
    protected void shutDown() {
        started = false;
        localTesting = false;
        CaptureFocus focus = captureFocus;
        captureFocus = null;
        if (focus != null) {
            focus.close();
        }
        leave("Disconnected");
        pendingRoster.set(null);
        partySocket.unregisterMessage(RsVcPartyVoice.class);
        observer = VoiceObserver.NONE;
        overlayManager.remove(speakingOverlay);
        keyManager.unregisterKeyListener(this);
        keyManager.unregisterKeyListener(muteHotkey);
        keyManager.unregisterKeyListener(deafenHotkey);
        muteHotkey.focusLost();
        deafenHotkey.focusLost();
        devicePicker.close();
        if (panel != null) {
            panel.close();
        }
        SwingUtilities.invokeLater(
                () -> {
                    if (navigation != null) {
                        toolbar.removeNavigation(navigation);
                    }
                    navigation = null;
                });
    }

    private void status(String text) {
        VoicePanel current = panel;
        if (current != null) {
            current.status(text);
        }
    }

    private void join() {
        if (voice.connection() != null || voice.retryPending()) {
            return;
        }
        leave("Connecting…");
        if (!started) {
            return;
        }
        voice.requestConnection();
        Player player = client.getLocalPlayer();
        if (client.getGameState() != GameState.LOGGED_IN || player == null) {
            status("Waiting for login");
            return;
        }
        try {
            VoiceConnection.validateEndpoint(relayEndpoint());
        } catch (IllegalArgumentException e) {
            voice.cancelConnectionRequest();
            status(e.getMessage());
            return;
        }
        voice.newIdentity();
        if (panel != null) {
            panel.alias(voice.alias());
            panel.connectionActive(true);
        }
        openConnection();
    }

    private void openConnection() {
        VoiceConnection next = voice.open(gson, observer, new VoiceClient.Listener() {
            @Override
            public void status(VoiceConnection source, String message) {
                clientThread.invokeLater(() -> {
                    if (voice.owns(source)) {
                        if (panel != null) {
                            panel.connected(source.isOpen());
                        }
                        RsVcPlugin.this.status(message);
                    }
                });
            }

            @Override
            public void roster(VoiceConnection source, List<VoiceConnection.Peer> roster) {
                pendingRoster.set(() -> applyRoster(source, roster));
            }

            @Override
            public void audio(VoiceConnection source, VoicePacket packet) {
                AudioEngine current = audio;
                if (voice.owns(source) && current != null && voice.audioAllowed()) {
                    current.receive(packet);
                }
            }

            @Override
            public void ended(VoiceConnection source, DisconnectReason reason) {
                clientThread.invokeLater(() -> onConnectionEnded(source, reason));
            }

            @Override
            public void room(VoiceConnection source, VoiceConnection.RoomState state) {
                if (!voice.owns(source)) {
                    return;
                }
                AudioEngine current = audio;
                if (current != null && (!voice.roomCode().equals(state.code)
                        || "unavailable".equals(state.reason))) {
                    current.clearPlayback();
                }
                clientThread.invokeLater(() -> applyRoom(source, state));
            }
        });
        audio = new AudioEngine(
                config.microphone(), config.speakers(),
                () -> Math.max(0, Math.min(100, config.volume())),
                packet -> {
                    if (voice.owns(next) && held && !muted && !deaf && voice.audioAllowed()) {
                        next.transmit(packet);
                    }
                },
                next::canTransmit,
                message -> clientThread.invokeLater(() -> {
                    if (voice.owns(next)) {
                        leave(message);
                    }
                }), true, observer);
        audio.frameMillis(next::frameMillis);
        audio.gate(gateSettings);
        audio.deafen(deaf);
        updateListening();
        try {
            next.connect(http, relayEndpoint());
        } catch (RuntimeException e) {
            leave("Could not connect: " + e.getMessage());
        }
    }

    private void applyRoster(VoiceConnection source, List<VoiceConnection.Peer> roster) {
        if (!voice.owns(source)) {
            return;
        }
        for (VoiceConnection.Peer previous : peers) {
            if (roster.stream().noneMatch(p -> p.id == previous.id) && audio != null) {
                audio.block(previous.id);
            }
        }
        peers = roster;
        refreshPeers();
        updateListening();
        if (held) {
            captureStatus(source);
        } else if (roster.isEmpty()) {
            status("No other voices");
        } else if (!source.canTransmit()) {
            status("No listeners available");
        } else {
            status(config.voiceMode() == VoiceMode.PUSH_TO_TALK
                    ? "Connected — hold push-to-talk to speak" : "Connected — voice-activated mode");
        }
    }

    private void applyRoom(VoiceConnection source, VoiceConnection.RoomState state) {
        boolean changed = !voice.roomCode().equals(state.code);
        if (!voice.acceptRoom(source, state)) {
            return;
        }
        if (state.restorationFailed) {
            release();
            if (panel != null) {
                panel.roomState(state.code, false);
                panel.roomRecovery(true);
            }
            status("Voice paused — room " + state.reason + "; retry room or return to nearby");
            return;
        }
        if (panel != null) {
            panel.roomRecovery(voice.recoveryPaused());
        }
        if ("full".equals(state.reason)) {
            boolean party = voice.partySelected();
            stopPartyVoice();
            source.requireRoom(null);
            updatePartyVoice();
            if (panel != null) {
                panel.roomState(state.code, false);
                panel.roomFull(party);
            }
            status(party ? "Party voice room full — try again later" : "Room full — try again later");
            return;
        }
        if (changed || "unavailable".equals(state.reason)) {
            release();
        }
        if (voice.partySelected()) {
            partyVoice.roomChanged(state.code, state.reason, monotonicMillis());
            updatePartyVoice();
            return;
        }
        if (panel != null) {
            panel.roomState(state.code, "created".equals(state.reason));
        }
        if ("unavailable".equals(state.reason)) {
            status("Room unavailable — current voice selection unchanged");
        } else if ("created".equals(state.reason)) {
            status("Room created — Room → Share code");
        }
    }

    private void onConnectionEnded(VoiceConnection source, DisconnectReason reason) {
        Long delay = voice.disconnected(source, reason);
        if (delay == null) {
            return;
        }
        if (voice.partySelected()) {
            partyVoice.reconnect();
        }
        stopAudio();
        visiblePlayers.clear();
        trackedView = null;
        peers = Collections.emptyList();
        blocked.clear();
        if (panel != null) {
            panel.roomsEnabled(false);
            panel.connected(false);
        }
        log.debug("RSVC reconnect: relay={}, category={}, partySelected={}, retryDelayMs={}",
                localTesting ? "local" : "hosted", reason, voice.partySelected(), delay);
        if (delay < 0) {
            stopPartyVoice();
            if (panel != null) {
                panel.alias("");
                panel.connectionActive(false);
            }
            status("Disconnected — relay rejection or repeated identity conflict");
            return;
        }
        if (reason == DisconnectReason.ALIAS_IN_USE) {
            if (panel != null) {
                panel.alias(voice.alias());
            }
            status("Alias was taken — retrying with a new random alias");
        } else if (reason == DisconnectReason.IDENTITY_IN_USE) {
            status("Character already connected — waiting for the previous connection to clear");
        } else if (reason == DisconnectReason.SERVER_FULL) {
            status("Voice server full — retrying automatically in " + delay / 1000 + " seconds");
        } else {
            status(localTesting
                    ? "Local relay interrupted — start it or turn off local testing"
                    : "Voice interrupted — reconnecting shortly; release push-to-talk");
        }
    }

    private String relayEndpoint() {
        return localTesting ? "ws://127.0.0.1:8787/v1/voice" : RsVcConfig.HOSTED_RELAY;
    }

    /** Optional dev tooling only; call on the client thread. Never reads saved release settings. */
    public void useLocalTestRelay(boolean enabled) {
        if (localTesting == enabled) {
            return;
        }
        localTesting = enabled;
        if (started) {
            restartConnection("Updating connection settings");
        }
    }

    /** Attach/detach optional tooling on the client thread; no counters exist in the plugin. */
    public boolean observe(VoiceObserver next) {
        observer = started ? java.util.Objects.requireNonNull(next) : VoiceObserver.NONE;
        if (voice.connection() != null) {
            voice.connection().observer(observer);
        } else {
            observer.connected(false);
        }
        if (audio != null) {
            audio.observer(observer);
        }
        return started;
    }

    /**
     * Give a local diagnostic exclusive device ownership until Connect, settings change or
     * shutdown.
     */
    public boolean beginLocalAudioTest(Runnable cleanup, BooleanSupplier speaking) {
        if (!started) {
            return false;
        }
        leave("Local audio test");
        localTestCleanup = java.util.Objects.requireNonNull(cleanup);
        localTestSpeaking = java.util.Objects.requireNonNull(speaking);
        return true;
    }

    public void endLocalAudioTest(Runnable owner) {
        if (localTestCleanup == owner) {
            endLocalAudioTest();
        }
    }

    private void endLocalAudioTest() {
        Runnable cleanup = localTestCleanup;
        localTestCleanup = null;
        localTestSpeaking = null;
        speakingPlayers = Collections.emptyList();
        if (cleanup != null) {
            cleanup.run();
        }
    }

    private void stopAudio() {
        endLocalAudioTest();
        matchedPlayers.clear();
        speakingPlayers = Collections.emptyList();
        voice.invalidateAudio();
        release();
        AudioEngine current = audio;
        audio = null;
        if (current != null) {
            current.close();
        }
        VoicePanel view = panel;
        if (view != null) {
            view.peers(Collections.emptyList());
        }
    }

    private void leave(String message) {
        stopPartyVoice();
        voice.disconnect();
        stopAudio();
        blocked.clear();
        status(message);
        mutedNames.clear();
        speakerVolumes.clear();
        peers = Collections.emptyList();
        visiblePlayers.clear();
        trackedView = null;
        matcher.clear();
        if (panel != null) {
            panel.mutedCount(0);
            panel.alias("");
            panel.connectionActive(false);
            panel.roomState("");
            panel.roomsEnabled(false);
            panel.partyState(partyService.isInParty(), false, false);
        }
    }

    private void restartConnection(String message) {
        boolean resume = voice.connectionWanted();
        leave(message);
        if (resume) {
            voice.requestConnection();
        }
    }

    private void awaitLogin() {
        restartConnection(voice.connectionWanted() ? "Waiting for login" : "Disconnected");
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        switch (voice.tick(voiceGameState(client.getGameState()), started)) {
            case JOIN:
                join();
                break;
            case RECONNECT:
                openConnection();
                break;
            case WAIT_FOR_LOGIN:
                awaitLogin();
                return;
            default:
                break;
        }
        updateProximity();
        updatePartyVoice();
    }

    private static long monotonicMillis() {
        return System.nanoTime() / 1_000_000L;
    }

    private void togglePartyVoice() {
        if (!started) {
            return;
        }
        if (voice.partySelected()) {
            leavePartyVoice("Left party voice — nearby voice");
            return;
        }
        if (partyJoin.pending()) {
            // The party voice button remains enabled while waiting so a second click cancels.
            partyJoin.cancel();
            updatePartyVoice();
            status("Party voice cancelled");
            return;
        }
        VoiceConnection current = voice.connection();
        if (!partyService.isInParty() || current == null) {
            status("Connect voice and join a RuneLite party first");
            return;
        }
        if (!partyReady(current)) {
            // RuneLite reports the party before its own member record; wait instead of
            // dropping the click.
            partyJoin.request(monotonicMillis());
            updatePartyVoice();
            status("Joining party voice — waiting for the party to sync");
            return;
        }
        startPartyVoice(current);
    }

    private boolean partyReady(VoiceConnection current) {
        return partyService.isInParty()
                && partyService.getLocalMember() != null
                && current != null
                && current.roomsAvailable();
    }

    private void startPartyVoice(VoiceConnection current) {
        partyVoice.start(
                partyService.getPartyId(),
                partyService.getLocalMember().getMemberId(),
                localTesting,
                monotonicMillis());
        voice.selectParty();
        if (panel != null) {
            panel.roomRecovery(false);
        }
        current.requireRoom("");
        release();
        if (audio != null) {
            audio.clearPlayback();
        }
        peers = Collections.emptyList();
        refreshPeers();
        updatePartyVoice();
        status("Joining party voice");
    }

    private void setMicrophoneMuted(boolean value) {
        if (!started) {
            return;
        }
        muted = value;
        release();
        if (panel != null) {
            panel.microphoneMuted(value);
        }
    }

    private void recoverRoom(boolean retry) {
        VoiceConnection current = voice.connection();
        if (!started || voice.partySelected() || current == null) {
            return;
        }
        boolean accepted = voice.recoverRoom(retry);
        if (!accepted) {
            return;
        }
        release();
        if (audio != null) {
            audio.clearPlayback();
        }
        if (panel != null) {
            panel.roomRecovery(false);
            panel.roomState(current.roomCode());
        }
        status(retry ? "Rejoining room…" : "Nearby voice");
    }

    private void setDeafened(boolean value) {
        if (!started) {
            return;
        }
        deaf = value;
        release();
        if (audio != null) {
            audio.deafen(value);
        }
        updateListening();
        if (panel != null) {
            panel.deafened(value);
        }
    }

    private void leavePartyVoice(String message) {
        partyJoin.cancel();
        boolean resume = voice.connectionWanted();
        // Closing cancels any in-flight room creation/join before returning to nearby voice.
        leave(message);
        if (resume) {
            voice.requestConnection();
        }
    }

    private void stopPartyVoice() {
        partyJoin.cancel();
        if (!voice.partySelected()) {
            return;
        }
        boolean notify = partyVoice.sameParty(partyService.getPartyId());
        voice.stopParty();
        partyVoice.stop();
        if (notify) {
            sendPartyVoice();
        }
    }

    private void sendPartyVoice() {
        if (!partyService.isInParty() || partyService.getLocalMember() == null) {
            return;
        }
        try {
            partyService.send(partyVoice.message());
        } catch (IllegalStateException disconnected) {
            // RuneLite may close its party socket concurrently. Periodic discovery retries.
        }
    }

    private void updatePartyVoice() {
        if (!started) {
            return;
        }
        VoiceConnection current = voice.connection();
        boolean inParty = partyService.isInParty() && partyService.getLocalMember() != null;
        if (partyJoin.pending() && !partyService.isInParty()) {
            partyJoin.cancel();
            status("Left the party — party voice cancelled");
        }
        switch (partyJoin.step(!voice.partySelected() && partyReady(current), monotonicMillis())) {
            case START:
                startPartyVoice(current);
                return;
            case EXPIRED:
                status("Couldn't join party voice — the party didn't sync; try again");
                break;
            default:
                break;
        }
        if (voice.partySelected() && !partyVoice.sameParty(partyService.getPartyId())) {
            leavePartyVoice("Party changed — nearby voice");
            return;
        }
        if (voice.partySelected()) {
            long now = monotonicMillis();
            Set<Long> members = new HashSet<>();
            partyService.getMembers().forEach(member -> members.add(member.getMemberId()));
            partyVoice.retainMembers(members, now);
            if (inParty && partyVoice.advertisementDue(now)) {
                sendPartyVoice();
            }
            if (current != null) {
                PartyVoice.Command command =
                        inParty && current.roomsAvailable()
                                ? partyVoice.nextCommand(current.roomCode(), now)
                                : null;
                String required = inParty ? partyVoice.requiredRoom() : "";
                current.requireRoom(required);
                if (required.isEmpty()) {
                    release();
                    if (audio != null) {
                        audio.clearPlayback();
                    }
                }
                if (command != null) {
                    current.room(command.action, command.code);
                }
            }
        }
        if (panel != null) {
            panel.roomsEnabled(current != null && current.roomsAvailable());
            panel.partyState(
                    inParty || partyJoin.pending(),
                    voice.partySelected() || partyJoin.pending(),
                    voice.partySelected()
                            && inParty
                            && current != null
                            && !partyVoice.requiredRoom().isEmpty()
                            && partyVoice.requiredRoom().equals(current.roomCode()));
        }
    }

    @Subscribe
    public void onPartyChanged(PartyChanged event) {
        if (voice.partySelected()) {
            VoiceConnection current = voice.connection();
            if (current != null) {
                current.requireRoom("");
            }
            clientThread.invokeLater(
                    () -> {
                        if (started && voice.partySelected()) {
                            leavePartyVoice("Party changed — nearby voice");
                        }
                    });
        }
    }

    @Subscribe
    public void onRsVcPartyVoice(RsVcPartyVoice event) {
        clientThread.invokeLater(
                () -> {
                    if (!started
                            || !voice.partySelected()
                            || !partyVoice.sameParty(partyService.getPartyId())
                            || partyService.getMemberById(event.getMemberId()) == null) {
                        return;
                    }
                    partyVoice.receive(event, monotonicMillis());
                    updatePartyVoice();
                });
    }

    @Subscribe
    public void onUserSync(UserSync event) {
        clientThread.invokeLater(
                () -> {
                    if (started && voice.partySelected()) {
                        partyVoice.requestAdvertisement();
                    }
                });
    }

    @Subscribe
    public void onPlayerSpawned(PlayerSpawned event) {
        if (voice.connection() != null) {
            visiblePlayers.add(event.getPlayer());
        }
    }

    @Subscribe
    public void onPlayerDespawned(PlayerDespawned event) {
        visiblePlayers.remove(event.getPlayer());
        matchedPlayers.values().removeIf(player -> player == event.getPlayer());
    }

    private void updateProximity() {
        VoiceConnection current = voice.connection();
        Player self = client.getLocalPlayer();
        if (current == null || client.getGameState() != GameState.LOGGED_IN || self == null) {
            return;
        }
        String salt = current.matchingSalt();
        if (salt.isEmpty() || self.getName() == null || self.getWorldView() == null) {
            return;
        }
        WorldView view = self.getWorldView();
        if (view != trackedView) {
            // Seed once when connecting or changing scenes; spawn/despawn events maintain this set.
            visiblePlayers.clear();
            for (Player player : view.players()) {
                visiblePlayers.add(player);
            }
            trackedView = view;
        }
        WorldPoint origin = self.getWorldLocation();
        Map<String, Player> namedPlayers = new HashMap<>();
        List<Player> inRange = new ArrayList<>();
        for (Player player : visiblePlayers) {
            if (player == self || player.getName() == null || player.getWorldView() != view) {
                continue;
            }
            WorldPoint point = player.getWorldLocation();
            if (point.getPlane() != origin.getPlane()) {
                continue;
            }
            if (ProximityMatcher.inRange(
                    origin.getX(),
                    origin.getY(),
                    origin.getPlane(),
                    point.getX(),
                    point.getY(),
                    point.getPlane(),
                    true)) {
                namedPlayers.put(player.getName(), player);
                inRange.add(player);
            } else if (current.inRoom()) {
                // A room member may be visible outside the ordinary proximity radius.
                namedPlayers.put(player.getName(), player);
            }
        }
        try {
            Map<String, Long> matches =
                    matcher.matchNames(
                            salt, client.getWorld(), namedPlayers.keySet(), current.introductions());
            matchedPlayers.clear();
            matches.forEach((name, id) -> matchedPlayers.put(id, namedPlayers.get(name)));
            // Nearest first, so a crowd beyond either cap keeps the closest characters.
            inRange.sort(Comparator.comparingInt(p -> p.getWorldLocation().distanceTo(origin)));
            // Every confirmed peer in range; the relay decides who shares audio.
            Set<Long> nearby = new HashSet<>();
            List<String> names = new ArrayList<>();
            for (Player player : inRange) {
                names.add(player.getName());
                Long id = matches.get(player.getName());
                if (id != null && nearby.size() < VoiceConnection.MAX_SEEN) {
                    nearby.add(id);
                }
            }
            Set<String> seen =
                    matcher.fingerprints(salt, client.getWorld(), names, VoiceConnection.MAX_SEEN);
            voice.position(salt, self.getName(), client.getWorld(), nearby, seen);
            if (!current.inRoom()) {
                for (VoiceConnection.Peer peer : peers) {
                    if (!nearby.contains(peer.id) && audio != null) {
                        audio.block(peer.id);
                    }
                }
            }
            if (panel != null) {
                panel.roomsEnabled(current.roomsAvailable());
            }
        } catch (IllegalArgumentException invalid) {
            pause("Voice paused — character unavailable");
        }
    }

    @Subscribe
    public void onClientTick(ClientTick tick) {
        if (started) {
            handleGameState(client.getGameState());
        }
        Runnable rosterUpdate = pendingRoster.getAndSet(null);
        if (started && rosterUpdate != null) {
            rosterUpdate.run();
        }
        updateSpeakingIndicators();
        VoiceConnection current = voice.connection();
        if (current == null) {
            return;
        }
        if (!started) {
            leave("Disconnected");
            return;
        }
        voice.heartbeat(muted, deaf);
        if (config.voiceMode() == VoiceMode.VOICE_ACTIVATED) {
            if (canCapture(current)) {
                if (!held) {
                    held = true;
                    audio.startCapture();
                    captureStatus(current);
                }
            } else {
                release();
            }
        } else if (held && !canCapture(current)) {
            release();
        }
    }

    private boolean canCapture(VoiceConnection current) {
        CaptureFocus focus = captureFocus;
        return started
                && (config.voiceMode() == VoiceMode.VOICE_ACTIVATED
                        ? focus != null && focus.isActive()
                        : focused)
                && !muted
                && !deaf
                && voice.eligible()
                && audio != null
                && current != null
                && current.isOpen()
                && !current.awaitingRoomRecovery()
                && (current.canTransmit() || config.speakingIndicators());
    }

    private void captureStatus(VoiceConnection current) {
        status(current.canTransmit() ? "Microphone on" : "Local mic only");
    }

    private void pause(String reason) {
        voice.pause();
        release();
        if (audio != null) {
            audio.clearPlayback();
        }
        visiblePlayers.clear();
        matchedPlayers.clear();
        speakingPlayers = Collections.emptyList();
        trackedView = null;
        matcher.clear();
        status(reason);
    }

    private void updateListening() {
        Set<Long> nextBlocked = new HashSet<>();
        Set<String> quiet = new HashSet<>(mutedNames);
        Map<Long, Integer> levels = new HashMap<>();
        for (Map.Entry<String, Integer> entry : speakerVolumes.entrySet()) {
            if (entry.getValue() == 0) {
                quiet.add(entry.getKey());
            }
        }
        for (VoiceConnection.Peer peer : peers) {
            if (quiet.contains(peer.name)) {
                nextBlocked.add(peer.id);
            }
            levels.put(peer.id, speakerVolumes.getOrDefault(peer.name, 100));
        }
        blocked.clear();
        blocked.addAll(nextBlocked);
        VoiceConnection current = voice.connection();
        if (current != null) {
            current.mutedAliases(quiet);
            current.listening(deaf, blocked);
        }
        if (audio != null) {
            audio.volumes(levels);
            for (long id : blocked) {
                audio.block(id);
            }
        }
        if (panel != null) {
            panel.mutedCount(quiet.size());
        }
    }

    private void refreshPeers() {
        if (panel != null) {
            panel.peers(peers, new HashMap<>(speakerVolumes), new HashSet<>(mutedNames));
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        handleGameState(event.getGameState());
    }

    private void handleGameState(GameState state) {
        boolean wasEligible = voice.eligible();
        VoiceClient.GameUpdate update = voice.gameState(
                voiceGameState(state), state == GameState.LOGGED_IN && client.getLocalPlayer() != null);
        if (update == VoiceClient.GameUpdate.LOGGED_OUT) {
            awaitLogin();
        } else if (update == VoiceClient.GameUpdate.POSITION_UNAVAILABLE) {
            if (wasEligible && !voice.eligible()) {
                release();
                if (audio != null) {
                    audio.clearPlayback();
                }
                status("Nearby voice paused — waiting for position updates");
            }
            visiblePlayers.clear();
            matchedPlayers.clear();
            speakingPlayers = Collections.emptyList();
            trackedView = null;
            matcher.clear();
        }
    }

    static VoiceClient.GameState voiceGameState(GameState state) {
        switch (state) {
            case LOGGED_IN:
                return VoiceClient.GameState.LOGGED_IN;
            case LOADING:
            case HOPPING:
            case CONNECTION_LOST:
            case LOGGING_IN:
                return VoiceClient.GameState.TRANSITION;
            default:
                return VoiceClient.GameState.LOGGED_OUT;
        }
    }

    @Subscribe
    public void onFocusChanged(FocusChanged event) {
        focused = event.isFocused();
        if (!focused) {
            keyDown = false;
            if (config.voiceMode() == VoiceMode.PUSH_TO_TALK) {
                release();
            }
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!RsVcConfig.GROUP.equals(event.getGroup())) {
            return;
        }
        if ("muteHotkey".equals(event.getKey()) || "deafenHotkey".equals(event.getKey())) {
            SwingUtilities.invokeLater(() -> {
                muteHotkey.focusLost();
                deafenHotkey.focusLost();
            });
            return;
        }
        // Retired keys cannot change the fixed destination or grant/revoke a live session.
        if ("consent".equals(event.getKey())
                || "endpoint".equals(event.getKey())
                || "baselineAudio".equals(event.getKey())
                || "noiseReduction".equals(event.getKey())) {
            return;
        }
        // Capture policy is local: preserve the socket, room and participant preferences.
        if ("voiceMode".equals(event.getKey()) || "pushToTalk".equals(event.getKey())) {
            clientThread.invokeLater(
                    () -> {
                        endLocalAudioTest();
                        release();
                        keyDown = false;
                        // Voice activation resumes on the next tick if capture is eligible.
                    });
            return;
        }
        if ("microphone".equals(event.getKey()) || "speakers".equals(event.getKey())) {
            clientThread.invokeLater(
                    () -> {
                        endLocalAudioTest();
                        AudioEngine current = audio;
                        if (current != null
                                && current.changeDevices(config.microphone(), config.speakers())) {
                            release();
                            keyDown = false;
                            status("Audio devices updated");
                        }
                    });
            return;
        }
    }

    @Override
    public void keyPressed(KeyEvent event) {
        if (config.voiceMode() != VoiceMode.PUSH_TO_TALK
                || !config.pushToTalk().matches(event)
                || keyDown) {
            return;
        }
        keyDown = true;
        AudioEngine current = audio;
        VoiceConnection network = voice.connection();
        if (!held && canCapture(network)) {
            held = true;
            current.startCapture();
            captureStatus(network);
        }
    }

    @Override
    public void keyReleased(KeyEvent event) {
        if (event.getKeyCode() == config.pushToTalk().getKeyCode()
                || !config.pushToTalk().matches(event)) {
            keyDown = false;
            if (config.voiceMode() == VoiceMode.PUSH_TO_TALK) {
                release();
            }
        }
    }

    @Override
    public void keyTyped(KeyEvent event) {}

    private void release() {
        boolean wasHeld = held;
        held = false;
        AudioEngine current = audio;
        if (current != null && wasHeld) {
            current.stopCapture();
        }
        if (wasHeld) {
            status("Connected — microphone idle");
        }
    }

    private void updateSpeakingIndicators() {
        long now = System.nanoTime();
        if (now < nextSpeakingUpdate) {
            return;
        }
        nextSpeakingUpdate = now + 100_000_000L;
        Player self = client.getLocalPlayer();
        if (!started
                || !config.speakingIndicators()
                || client.getGameState() != GameState.LOGGED_IN
                || self == null) {
            speakingPlayers = Collections.emptyList();
            return;
        }
        List<Player> active = new ArrayList<>();
        BooleanSupplier testSpeaking = localTestSpeaking;
        AudioEngine current = audio;
        boolean live = voice.audioAllowed();
        if ((testSpeaking != null && testSpeaking.getAsBoolean())
                || (live
                        && current != null
                        && held
                        && !muted
                        && !deaf
                        && current.microphoneSpeaking())) {
            active.add(self);
        }
        if (live && current != null && !deaf) {
            for (long id : current.speaking()) {
                Player player = matchedPlayers.get(id);
                if (player != null && visiblePlayers.contains(player) && !blocked.contains(id)) {
                    active.add(player);
                }
            }
        }
        speakingPlayers = active;
    }
}

package com.rsvc;

public enum VoiceMode {
    PUSH_TO_TALK("Push-to-talk"),
    VOICE_ACTIVATED("Voice-activated");
    private final String label;

    VoiceMode(String label) {
        this.label = label;
    }

    @Override
    public String toString() {
        return label;
    }
}

package com.rsvc;

/** Optional instrumentation. The release plugin retains no traffic counters or audio recordings. */
public interface VoiceObserver {
    VoiceObserver NONE = new VoiceObserver() {};

    default void connected(boolean connected) {}

    default void idle() {}

    default void encoded(int bytes, boolean suppressed) {}

    default void message(boolean outgoing, boolean audio, int bytes) {}
}

package com.rsvc.audio;

import com.rsvc.VoiceObserver;
import com.rsvc.network.VoicePacket;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import java.util.function.IntSupplier;

import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.DataLine;
import javax.sound.sampled.Line;
import javax.sound.sampled.Mixer;
import javax.sound.sampled.SourceDataLine;
import javax.sound.sampled.TargetDataLine;

/** Audio devices and codec run on dedicated threads, never the game or Swing thread. */
public final class AudioEngine implements AutoCloseable {
    static final AudioFormat FORMAT = new AudioFormat(48000, 16, 1, true, false);
    private final PlaybackBuffer playback = new PlaybackBuffer();
    private final SpeechActivity microphoneActivity = new SpeechActivity();
    // Kept across capture restarts so the learned background level survives device changes.
    private final NoiseGate gate = new NoiseGate();
    private volatile NoiseGate.Settings gateSettings = NoiseGate.Settings.OFF;
    private final ExecutorService input = executor("RS VC capture");
    private final ExecutorService output = executor("RS VC playback");
    private final ExecutorService devices;
    private final LineProvider lines;
    private final AtomicLong captureEpoch = new AtomicLong();
    private final AtomicLong playbackEpoch = new AtomicLong();
    private final Consumer<byte[]> transmit;
    private final BooleanSupplier audience;
    private final Consumer<String> error;
    private final IntSupplier volume;
    private volatile String microphone;
    private volatile String speakers;
    private final boolean suppressSilence;
    private volatile VoiceObserver observer;
    private volatile AudioDevice<TargetDataLine> capture;
    private volatile AudioDevice<SourceDataLine> speaker;
    private volatile boolean closed;
    private volatile boolean deaf;
    private volatile IntSupplier frameMillis = () -> 20;
    private long sequence;

    interface LineProvider {
        Line get(boolean input, String name) throws Exception;
    }

    private static final class AudioDevice<T extends DataLine> {
        private final T line;
        private boolean closed;
        private long flushGeneration;

        private AudioDevice(T line) {
            this.line = line;
        }

        // A JavaSound mixer may return the same line for the next capture. The
        // input worker must finish this close before reopening it, and a delayed
        // cleanup task must not close that newer capture.
        private synchronized void close() {
            if (!closed) {
                closed = true;
                line.close();
            }
        }

        private synchronized void flush() {
            if (!closed) {
                flushGeneration++;
                line.flush();
            }
        }

        private synchronized long flushGeneration() {
            return flushGeneration;
        }
    }

    public AudioEngine(
            String microphone,
            String speakers,
            IntSupplier volume,
            Consumer<byte[]> transmit,
            BooleanSupplier audience,
            Consumer<String> error,
            boolean suppressSilence,
            VoiceObserver observer) {
        this(
                microphone,
                speakers,
                volume,
                transmit,
                audience,
                error,
                suppressSilence,
                observer,
                AudioEngine::line,
                executor("RS VC device cleanup"));
    }

    AudioEngine(
            String microphone,
            String speakers,
            IntSupplier volume,
            Consumer<byte[]> transmit,
            BooleanSupplier audience,
            Consumer<String> error,
            boolean suppressSilence,
            VoiceObserver observer,
            LineProvider lines,
            ExecutorService devices) {
        this.lines = lines;
        this.devices = devices;
        this.microphone = microphone;
        this.speakers = speakers;
        this.volume = volume;
        this.transmit = transmit;
        this.audience = audience;
        this.error = error;
        this.suppressSilence = suppressSilence;
        this.observer = observer;
        output.execute(() -> play(speakers, 0));
    }

    /** Restart only device workers; preserve packet sequence, volumes and voice connection. */
    public boolean changeDevices(String microphone, String speakers) {
        if (closed || (this.microphone.equals(microphone) && this.speakers.equals(speakers))) {
            return false;
        }
        stopCapture();
        this.microphone = microphone;
        this.speakers = speakers;
        long epoch = playbackEpoch.incrementAndGet();
        playback.clear();
        AudioDevice<SourceDataLine> previous = speaker;
        if (previous != null) {
            deviceTask(previous::close);
        }
        try {
            output.execute(() -> play(speakers, epoch));
        } catch (java.util.concurrent.RejectedExecutionException ignored) {
            /* Shutdown raced a device selection. */
        }
        return true;
    }

    public void observer(VoiceObserver next) {
        observer = next;
    }

    private static ExecutorService executor(String name) {
        return Executors.newSingleThreadExecutor(
                r -> {
                    Thread t = new Thread(r, name);
                    t.setDaemon(true);
                    return t;
                });
    }

    public static List<String> devices(boolean input) {
        List<String> names = new ArrayList<>();
        DataLine.Info info =
                new DataLine.Info(input ? TargetDataLine.class : SourceDataLine.class, FORMAT);
        for (Mixer.Info mixer : AudioSystem.getMixerInfo()) {
            if (AudioSystem.getMixer(mixer).isLineSupported(info)) {
                names.add(mixer.getName());
            }
        }
        return names;
    }

    static Line line(boolean input, String name) throws Exception {
        DataLine.Info info =
                new DataLine.Info(input ? TargetDataLine.class : SourceDataLine.class, FORMAT);
        if (name.trim().isEmpty()) {
            return AudioSystem.getLine(info);
        }
        for (Mixer.Info mixer : AudioSystem.getMixerInfo()) {
            if (mixer.getName().equals(name) && AudioSystem.getMixer(mixer).isLineSupported(info)) {
                return AudioSystem.getMixer(mixer).getLine(info);
            }
        }
        throw new IllegalArgumentException("Audio device unavailable: " + name);
    }

    public void startCapture() {
        if (closed) {
            return;
        }
        long epoch = captureEpoch.incrementAndGet();
        try {
            input.execute(() -> capture(epoch));
        } catch (java.util.concurrent.RejectedExecutionException ignored) {
            /* Shutdown raced a key press. */
        }
    }

    public void stopCapture() {
        captureEpoch.incrementAndGet();
        microphoneActivity.clear();
        observer.idle();
        AudioDevice<TargetDataLine> current = capture;
        if (current != null) {
            deviceTask(current::close);
        } // Unblocks read without blocking the game thread.
    }

    private void deviceTask(Runnable task) {
        try {
            devices.execute(task);
        } catch (java.util.concurrent.RejectedExecutionException ignored) {
            /* Already closing. */
        }
    }

    private void capture(long epoch) {
        TargetDataLine device = null;
        AudioDevice<TargetDataLine> session = null;
        try {
            if (closed || epoch != captureEpoch.get()) {
                return;
            }
            device = (TargetDataLine) lines.get(true, microphone);
            session = new AudioDevice<>(device);
            device.open(FORMAT, OpusCodec.SAMPLES * 2 * 4);
            capture = session;
            if (closed || epoch != captureEpoch.get()) {
                return;
            }
            device.start();
            CaptureProcessor processor =
                    new CaptureProcessor(microphoneActivity, suppressSilence, gate);
            while (!closed && epoch == captureEpoch.get()) {
                // The relay chooses 20 or 40 ms packets; read one packet of audio.
                int frames = frameMillis.getAsInt() == 40 ? 2 : 1;
                byte[] bytes = new byte[OpusCodec.SAMPLES * 2 * frames];
                int offset = 0;
                while (offset < bytes.length && !closed && epoch == captureEpoch.get()) {
                    int read = device.read(bytes, offset, bytes.length - offset);
                    if (read <= 0) {
                        if (!closed && epoch == captureEpoch.get()) {
                            throw new IllegalStateException("Microphone stopped delivering audio");
                        }
                        return;
                    }
                    offset += read;
                }
                if (closed || epoch != captureEpoch.get()) {
                    return;
                }
                short[] pcm = new short[OpusCodec.SAMPLES * frames];
                for (int i = 0; i < pcm.length; i++) {
                    pcm[i] = (short) ((bytes[2 * i] & 255) | (bytes[2 * i + 1] << 8));
                }
                List<CaptureProcessor.Packet> encoded =
                        processor.process(
                                pcm,
                                audience.getAsBoolean(),
                                System.nanoTime() / 1_000_000,
                                observer,
                                gateSettings);
                // Counts 20 ms frames, including omitted ones, so receivers can identify gaps.
                // A pre-roll packet keeps the sequence it was captured with.
                long frameSequence = sequence;
                sequence += frames;
                if (closed || epoch != captureEpoch.get()) {
                    return;
                }
                for (CaptureProcessor.Packet packet : encoded) {
                    if (audience.getAsBoolean() && !closed && epoch == captureEpoch.get()) {
                        transmit.accept(
                                VoicePacket.upstream(
                                        frameSequence - packet.framesBefore, packet.opus));
                    }
                }
            }
        } catch (Exception e) {
            if (!closed && epoch == captureEpoch.get()) {
                error.accept("Microphone unavailable: " + e.getMessage());
            }
        } finally {
            observer.idle();
            gate.stopped();
            if (session != null) {
                session.close();
            }
            if (capture == session) {
                capture = null;
            }
        }
    }

    private void play(String speakers, long epoch) {
        SourceDataLine device = null;
        AudioDevice<SourceDataLine> session = null;
        try {
            if (closed || epoch != playbackEpoch.get()) {
                return;
            }
            device = (SourceDataLine) lines.get(false, speakers);
            session = new AudioDevice<>(device);
            device.open(FORMAT, OpusCodec.SAMPLES * 2 * 4);
            speaker = session;
            if (closed || epoch != playbackEpoch.get()) {
                return;
            }
            device.start();
            while (!closed && epoch == playbackEpoch.get()) {
                long generation = session.flushGeneration();
                short[] pcm =
                        deaf
                                ? new short[OpusCodec.SAMPLES]
                                : playback.mix(System.nanoTime() / 1_000_000, volume.getAsInt());
                byte[] bytes = new byte[pcm.length * 2];
                for (int i = 0; i < pcm.length; i++) {
                    bytes[2 * i] = (byte) pcm[i];
                    bytes[2 * i + 1] = (byte) (pcm[i] >> 8);
                }
                // The device's bounded buffer paces playback at 20 ms per frame.
                int offset = 0;
                while (!closed && epoch == playbackEpoch.get() && offset < bytes.length) {
                    if (generation != session.flushGeneration()) {
                        break;
                    }
                    int written = device.write(bytes, offset, bytes.length - offset);
                    // A flush legitimately interrupts a blocked write with zero or
                    // partial progress. Discard that frame and keep the device alive.
                    // Reading under the session lock also waits for flush to finish.
                    if (generation != session.flushGeneration()) {
                        break;
                    }
                    if (written <= 0) {
                        if (!closed && epoch == playbackEpoch.get()) {
                            throw new IllegalStateException("Speakers stopped accepting audio");
                        }
                        return;
                    }
                    offset += written;
                }
            }
        } catch (Exception e) {
            if (!closed && epoch == playbackEpoch.get()) {
                error.accept("Speakers unavailable: " + e.getMessage());
            }
        } finally {
            if (session != null) {
                session.close();
            }
            if (speaker == session) {
                speaker = null;
            }
        }
    }

    public void receive(VoicePacket packet) {
        if (closed || deaf) {
            return;
        }
        try {
            playback.offer(packet, System.nanoTime() / 1_000_000);
        } catch (Exception ignored) {
            playback.remove(packet.speaker);
        }
    }

    /** Voice-activation gate settings, read before each captured packet. */
    public void gate(NoiseGate.Settings value) {
        gateSettings = value;
    }

    /** Current microphone level for the meter, or null while the microphone is not capturing. */
    public NoiseGate.Level micLevel() {
        return closed ? null : gate.snapshot(System.nanoTime() / 1_000_000);
    }

    /** Packet duration in milliseconds (20 or 40), read before each captured packet. */
    public void frameMillis(IntSupplier value) {
        frameMillis = value;
    }

    public void deafen(boolean value) {
        deaf = value;
        clearPlayback();
    }

    public void clearPlayback() {
        playback.clear();
        AudioDevice<SourceDataLine> current = speaker;
        if (current != null) {
            deviceTask(current::flush);
        }
    }

    public void block(long id) {
        playback.remove(id);
    }

    public void volumes(java.util.Map<Long, Integer> values) {
        playback.volumes(values);
    }

    public boolean microphoneSpeaking() {
        return !closed && microphoneActivity.active(System.nanoTime() / 1_000_000);
    }

    public java.util.Set<Long> speaking() {
        return closed || deaf || volume.getAsInt() <= 0
                ? java.util.Collections.emptySet()
                : playback.speaking(System.nanoTime() / 1_000_000);
    }

    @Override
    public synchronized void close() {
        if (closed) {
            return;
        }
        closed = true;
        microphoneActivity.clear();
        captureEpoch.incrementAndGet();
        playback.clear();
        input.shutdownNow();
        output.shutdownNow();
        // Let queued device cleanup finish off-thread before shutting down its executor.
        // Lines still opening are closed by capture/play's finally blocks.
        deviceTask(
                () -> {
                    try {
                        AudioDevice<TargetDataLine> currentCapture = capture;
                        try {
                            if (currentCapture != null) {
                                currentCapture.close();
                            }
                        } finally {
                            AudioDevice<SourceDataLine> currentSpeaker = speaker;
                            if (currentSpeaker != null) {
                                currentSpeaker.close();
                            }
                        }
                    } finally {
                        devices.shutdownNow();
                    }
                });
    }
}

package com.rsvc.audio;

import com.rsvc.VoiceObserver;
import com.rsvc.codec.VoiceEncoder;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Mic activity stays local; only frames with an eligible audience reach the encoder. */
final class CaptureProcessor {
    /** An encoded packet; framesBefore is how many 20 ms frames it precedes the captured one. */
    static final class Packet {
        final byte[] opus;
        final int framesBefore;

        Packet(byte[] opus, int framesBefore) {
            this.opus = opus;
            this.framesBefore = framesBefore;
        }
    }

    private final SpeechActivity activity;
    private final boolean suppressSilence;
    private final NoiseGate gate;
    private VoiceEncoder encoder;
    // The packet captured just before the gate opened; sent first so word onsets survive.
    private short[] preRoll;

    CaptureProcessor(SpeechActivity activity, boolean suppressSilence) {
        this(activity, suppressSilence, new NoiseGate());
    }

    CaptureProcessor(SpeechActivity activity, boolean suppressSilence, NoiseGate gate) {
        this.activity = activity;
        this.suppressSilence = suppressSilence;
        this.gate = gate;
    }

    /** Packets to send for this captured audio, oldest first: none, one, or pre-roll and one. */
    List<Packet> process(
            short[] pcm,
            boolean audience,
            long nowMillis,
            VoiceObserver observer,
            NoiseGate.Settings settings) {
        boolean admitted = gate.admit(pcm, nowMillis, settings);
        if (settings.enabled()) {
            // The local indicator shows what voice activation would send.
            if (admitted) {
                activity.mark(nowMillis);
            }
        } else {
            activity.observe(pcm, nowMillis);
        }
        if (!audience) {
            // No encoded history from private, solo speech survives into a later transmission.
            encoder = null;
            preRoll = null;
            gate.close();
            observer.idle();
            return Collections.emptyList();
        }
        if (!admitted) {
            preRoll = pcm;
            observer.idle();
            return Collections.emptyList();
        }
        if (encoder == null) {
            encoder = OpusCodec.encoder(suppressSilence);
        }
        List<Packet> packets = new ArrayList<>(2);
        if (preRoll != null) {
            byte[] earlier = encode(preRoll, observer);
            if (earlier != null) {
                packets.add(new Packet(earlier, preRoll.length / OpusCodec.SAMPLES));
            }
            preRoll = null;
        }
        byte[] current = encode(pcm, observer);
        if (current != null) {
            packets.add(new Packet(current, 0));
        }
        return packets;
    }

    private byte[] encode(short[] pcm, VoiceObserver observer) {
        byte[] encoded = OpusCodec.encode(encoder, pcm);
        boolean suppressed = suppressSilence && OpusCodec.suppress(encoded);
        observer.encoded(encoded.length, suppressed);
        return suppressed ? null : encoded;
    }
}

package com.rsvc.audio;

/**
 * Voice-activation gate on raw microphone levels. Opus DTX only stops near-digital silence, so
 * steady hiss or fan noise would otherwise transmit. Auto learns the background level while the
 * gate is closed and opens a fixed margin above it; manual uses a fixed threshold. Single capture
 * thread; the meter reads the volatile snapshot fields.
 */
public final class NoiseGate {
    /** Live gate configuration, read before every captured packet. */
    public interface Settings {
        Settings OFF = new Settings() {};

        default boolean enabled() {
            return false;
        }

        default boolean auto() {
            return true;
        }

        default int manualDb() {
            return DEFAULT_MANUAL_DB;
        }
    }

    public static final int MIN_MANUAL_DB = -70;
    public static final int MAX_MANUAL_DB = -20;
    public static final int DEFAULT_MANUAL_DB = -45;
    static final double SILENCE_DB = -100;
    // Auto opens this far above the learned background, within these bounds.
    static final double AUTO_MARGIN_DB = 12;
    static final double AUTO_MIN_DB = -60;
    static final double AUTO_MAX_DB = -30;
    private static final double FLOOR_MIN_DB = -75;
    private static final double INITIAL_FLOOR_DB = -60;
    // Quiet rooms are learned quickly; a louder background is accepted slowly, and slower still
    // while the gate is open, so ongoing speech is not mistaken for noise.
    private static final double FALL_PER_SECOND = 20;
    private static final double RISE_CLOSED_PER_SECOND = 3;
    private static final double RISE_OPEN_PER_SECOND = 1;
    // Stays open between words and through word endings; small dips below the threshold
    // (hysteresis) also keep it open.
    static final long HOLD_MILLIS = 400;
    private static final double HYSTERESIS_DB = 3;

    private double floor = INITIAL_FLOOR_DB;
    private boolean open;
    private long lastLoud;
    private volatile double levelDb = SILENCE_DB;
    private volatile double thresholdDb = INITIAL_FLOOR_DB + AUTO_MARGIN_DB;
    private volatile boolean gating;
    private volatile boolean reportedOpen;
    private volatile long updatedAt = Long.MIN_VALUE;

    /** RMS level in dBFS: 0 is a full-scale square wave, digital silence is {@link #SILENCE_DB}. */
    public static double level(short[] pcm) {
        if (pcm.length == 0) {
            return SILENCE_DB;
        }
        double sum = 0;
        for (short sample : pcm) {
            sum += (double) sample * sample;
        }
        double rms = Math.sqrt(sum / pcm.length) / 32768;
        return rms <= 0 ? SILENCE_DB : Math.max(SILENCE_DB, 20 * Math.log10(rms));
    }

    /** Measures one packet and returns whether it may be sent. */
    boolean admit(short[] pcm, long nowMillis, Settings settings) {
        double level = level(pcm);
        double seconds = pcm.length / (double) OpusCodec.RATE;
        boolean enabled = settings.enabled();
        double threshold =
                settings.auto()
                        ? Math.max(AUTO_MIN_DB, Math.min(AUTO_MAX_DB, floor + AUTO_MARGIN_DB))
                        : Math.max(MIN_MANUAL_DB, Math.min(MAX_MANUAL_DB, settings.manualDb()));
        if (level >= threshold) {
            open = true;
            lastLoud = nowMillis;
        } else if (open && level >= threshold - HYSTERESIS_DB) {
            lastLoud = nowMillis;
        } else if (open && nowMillis - lastLoud > HOLD_MILLIS) {
            open = false;
        }
        double target = Math.max(FLOOR_MIN_DB, level);
        if (target < floor) {
            floor = Math.max(target, floor - FALL_PER_SECOND * seconds);
        } else {
            double rise = (open ? RISE_OPEN_PER_SECOND : RISE_CLOSED_PER_SECOND) * seconds;
            floor = Math.min(target, floor + rise);
        }
        levelDb = level;
        thresholdDb = threshold;
        gating = enabled;
        reportedOpen = !enabled || open;
        updatedAt = nowMillis;
        return !enabled || open;
    }

    /** A new talk spurt must cross the threshold again; the learned background is kept. */
    void close() {
        open = false;
    }

    /** Latest measurement for the level meter, or null when the microphone is not capturing. */
    public Level snapshot(long nowMillis) {
        long at = updatedAt;
        if (at == Long.MIN_VALUE || nowMillis - at > 250) {
            return null;
        }
        return new Level(levelDb, gating ? thresholdDb : Double.NaN, reportedOpen);
    }

    void stopped() {
        updatedAt = Long.MIN_VALUE;
        open = false;
    }

    /** A meter reading. Threshold is NaN when the gate is not in use (push-to-talk). */
    public static final class Level {
        public final double levelDb;
        public final double thresholdDb;
        public final boolean open;

        public Level(double levelDb, double thresholdDb, boolean open) {
            this.levelDb = levelDb;
            this.thresholdDb = thresholdDb;
            this.open = open;
        }
    }
}

package com.rsvc.audio;

import com.rsvc.codec.VoiceDecoder;
import com.rsvc.codec.VoiceEncoder;
import com.rsvc.network.VoicePacket;

import java.util.Arrays;

public final class OpusCodec {
    public static final int RATE = 48000;
    public static final int SAMPLES = 960;
    public static final int BITRATE = 16000;

    private OpusCodec() {}

    public static VoiceEncoder encoder() {
        return encoder(true);
    }

    public static VoiceEncoder encoder(boolean suppressSilence) {
        return new VoiceEncoder(BITRATE, suppressSilence);
    }

    public static VoiceDecoder decoder() {
        return new VoiceDecoder();
    }

    // Opus DTX emits a TOC-only/very small packet when there is nothing to transmit.
    // Do not apply a PCM volume gate: quiet speech must remain the encoder's decision.
    public static boolean suppress(byte[] packet) {
        return packet.length <= 2;
    }

    public static byte[] encode(VoiceEncoder encoder, short[] pcm) {
        byte[] out = new byte[VoicePacket.MAX_OPUS];
        int size = encoder.encode(pcm, out);
        return Arrays.copyOf(out, size);
    }
}

package com.rsvc.audio;

import com.rsvc.codec.VoiceDecoder;
import com.rsvc.network.VoicePacket;

import java.util.ArrayDeque;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

/** Bounded jitter queues and per-speaker decoders; all work is off the game thread. */
public final class PlaybackBuffer {
    private static final int MAX_SPEAKERS = 8;
    // Queued audio is counted in 20 ms playback frames; a 40 ms packet counts twice.
    private static final int MAX_QUEUED_FRAMES = 5;
    private static final int PRIMED_FRAMES = 2;
    // Short sequence gaps are lost audio and are concealed. Longer gaps are omitted silence.
    private static final int MAX_CONCEALED_GAP = 3;
    // Concealment played when a primed stream runs dry, so speech fades instead of clicking.
    private static final int UNDERRUN_CONCEALMENT = 2;
    private final Map<Long, Stream> streams = new HashMap<>();
    private Map<Long, Integer> volumes = java.util.Collections.emptyMap();

    public synchronized void volumes(Map<Long, Integer> values) {
        volumes = new HashMap<>(values);
    }

    private static final class Frame {
        final byte[] opus; // Null for a lost frame the decoder must conceal.
        final int frames;

        Frame(byte[] opus, int frames) {
            this.opus = opus;
            this.frames = frames;
        }
    }

    private static final class Stream {
        VoiceDecoder decoder = OpusCodec.decoder();
        final ArrayDeque<Frame> queue = new ArrayDeque<>();
        int queuedFrames;
        short[] carry; // Second half of a decoded 40 ms packet; counted in queuedFrames.
        long receivedAt;
        long sequence = -1;
        int packetFrames = 1;
        int concealed;
        boolean primed;
        final SpeechActivity activity = new SpeechActivity();

        void reset() {
            decoder = OpusCodec.decoder();
            queue.clear();
            queuedFrames = 0;
            carry = null;
            concealed = 0;
            primed = false;
        }

        void dropOldest() {
            if (carry != null) {
                carry = null;
                queuedFrames--;
            } else {
                queuedFrames -= queue.poll().frames;
            }
        }
    }

    public synchronized void offer(VoicePacket packet, long now) {
        int frames = frames(packet.opus);
        if (frames == 0) {
            // Only 20 and 40 ms packets are played, even if a hostile relay supplies valid Opus.
            return;
        }
        Stream stream = streams.get(packet.speaker);
        if (stream == null) {
            if (streams.size() >= MAX_SPEAKERS) {
                return;
            }
            stream = new Stream();
            streams.put(packet.speaker, stream);
        }
        long delta = (packet.sequence - stream.sequence) & 0xffffffffL;
        if (stream.sequence != -1 && (delta == 0 || delta >= 0x80000000L)) {
            return;
        }
        if (stream.sequence != -1) {
            // Sequences count 20 ms frames, including suppressed ones, so a long gap is
            // silence. Start fresh then; never synthesize/replay a long silent interval.
            long missing = delta - stream.packetFrames;
            if (missing > MAX_CONCEALED_GAP) {
                stream.reset();
            } else {
                for (long n = 0; n < missing; n++) {
                    stream.queue.add(new Frame(null, 1));
                    stream.queuedFrames++;
                }
            }
        }
        stream.sequence = packet.sequence;
        stream.packetFrames = frames;
        stream.receivedAt = now;
        stream.queue.add(new Frame(packet.opus, frames));
        stream.queuedFrames += frames;
        // Never play a growing backlog of old speech after TCP stalls. Keep the newest
        // audio at the priming depth instead of discarding everything and re-priming.
        if (stream.queuedFrames > MAX_QUEUED_FRAMES) {
            while (stream.queuedFrames > PRIMED_FRAMES) {
                stream.dropOldest();
            }
        }
    }

    private static int frames(byte[] opus) {
        // Zero for anything but the codec's own SILK-only wideband mono packets.
        return VoiceDecoder.samples(opus) / OpusCodec.SAMPLES;
    }

    public synchronized short[] mix(long now, int volume) {
        int[] sum = new int[OpusCodec.SAMPLES];
        Iterator<Map.Entry<Long, Stream>> iter = streams.entrySet().iterator();
        while (iter.hasNext()) {
            Map.Entry<Long, Stream> entry = iter.next();
            Stream stream = entry.getValue();
            if (now - stream.receivedAt > 200) {
                iter.remove();
                continue;
            }
            short[] pcm;
            boolean real;
            if (stream.carry != null) {
                pcm = stream.carry;
                real = true;
                stream.carry = null;
                stream.queuedFrames--;
            } else {
                if (!stream.primed
                        && stream.queuedFrames < PRIMED_FRAMES
                        && now - stream.receivedAt < 40) {
                    continue;
                }
                Frame frame = stream.queue.poll();
                if (frame == null) {
                    if (!stream.primed || stream.concealed >= UNDERRUN_CONCEALMENT) {
                        stream.primed = false;
                        continue;
                    }
                    stream.concealed++;
                    frame = new Frame(null, 1);
                } else {
                    stream.queuedFrames -= frame.frames;
                }
                stream.primed = true;
                real = frame.opus != null;
                if (real) {
                    stream.concealed = 0;
                }
                try {
                    short[] decoded = new short[frame.frames * OpusCodec.SAMPLES];
                    int size = stream.decoder.decode(frame.opus, decoded);
                    if (size != decoded.length) {
                        continue;
                    }
                    if (frame.frames == 2) {
                        pcm = java.util.Arrays.copyOf(decoded, OpusCodec.SAMPLES);
                        stream.carry =
                                java.util.Arrays.copyOfRange(
                                        decoded, OpusCodec.SAMPLES, decoded.length);
                        stream.queuedFrames++;
                    } else {
                        pcm = decoded;
                    }
                } catch (RuntimeException ignored) {
                    iter.remove();
                    continue;
                }
            }
            float gain =
                    Math.max(0, Math.min(100, volume))
                            / 100f
                            * Math.max(0, Math.min(200, volumes.getOrDefault(entry.getKey(), 100)))
                            / 100f;
            if (gain > 0 && real) {
                stream.activity.observe(pcm, now);
            }
            for (int i = 0; i < pcm.length; i++) {
                sum[i] += (int) (pcm[i] * gain);
            }
        }
        short[] result = new short[sum.length];
        for (int i = 0; i < sum.length; i++) {
            result[i] = (short) Math.max(Short.MIN_VALUE, Math.min(Short.MAX_VALUE, sum[i]));
        }
        return result;
    }

    public synchronized void clear() {
        streams.clear();
    }

    public synchronized void remove(long id) {
        streams.remove(id);
    }

    public synchronized java.util.Set<Long> speaking(long now) {
        java.util.Set<Long> result = new java.util.HashSet<>();
        streams.forEach(
                (id, stream) -> {
                    if (volumes.getOrDefault(id, 100) > 0 && stream.activity.active(now)) {
                        result.add(id);
                    }
                });
        return result;
    }

    synchronized int speakerCount() {
        return streams.size();
    }

    synchronized int queuedFrames(long speaker) {
        Stream stream = streams.get(speaker);
        return stream == null ? 0 : stream.queuedFrames;
    }
}

package com.rsvc.audio;

/** Visual audio activity only. Never gates, changes, or uploads audio. */
public final class SpeechActivity {
    private static final long HOLD_MILLIS = 200;
    private static final long MIN_RMS_SQUARED = 140L * 140;
    private volatile long lastActive = Long.MIN_VALUE;

    public void observe(short[] pcm, long nowMillis) {
        if (pcm.length == 0) {
            return;
        }
        long energy = 0;
        for (short sample : pcm) {
            energy += (long) sample * sample;
        }
        if (energy >= MIN_RMS_SQUARED * pcm.length) {
            lastActive = nowMillis;
        }
    }

    /** Marks speech decided elsewhere, such as an open voice-activation gate. */
    public void mark(long nowMillis) {
        lastActive = nowMillis;
    }

    public boolean active(long nowMillis) {
        long last = lastActive;
        return last != Long.MIN_VALUE && nowMillis >= last && nowMillis - last < HOLD_MILLIS;
    }

    public void clear() {
        lastActive = Long.MIN_VALUE;
    }
}

package com.rsvc.client;

import com.rsvc.client.VoiceClient.GameState;

/** Client-thread game state and position freshness, independent of room membership. */
final class GameVoiceSession {
    private GameState state = GameState.LOGGED_OUT;
    private long positionAt;

    void state(GameState next) {
        if (state != GameState.LOGGED_IN || next != GameState.LOGGED_IN) {
            invalidatePosition();
        }
        state = next;
    }

    boolean ended() {
        switch (state) {
            case LOGGED_IN:
            case TRANSITION:
                return false;
            default:
                return true;
        }
    }

    void positionUpdated(long now) {
        positionAt = now;
    }

    void invalidatePosition() {
        positionAt = 0;
    }

    boolean hasFreshPosition(long now) {
        return state == GameState.LOGGED_IN
                && positionAt != 0
                && now - positionAt < 2_500_000_000L;
    }
}

package com.rsvc.client;

import com.rsvc.network.DisconnectReason;

/** Network and capacity retries back off independently; policy and identity conflicts are bounded. */
public final class ReconnectPolicy {
    private int failures;
    private int aliasRetries;
    private int networkFailures;
    private int capacityFailures;

    public long nextDelayMillis(DisconnectReason reason) {
        if (reason == DisconnectReason.SERVER_FULL) {
            long delay = Math.min(30000, 4000L << capacityFailures);
            capacityFailures = Math.min(3, capacityFailures + 1);
            return delay;
        }
        if (reason == DisconnectReason.NETWORK) {
            long delay = Math.min(30000, 1000L << networkFailures);
            networkFailures = Math.min(5, networkFailures + 1);
            return delay;
        }
        if (reason == DisconnectReason.REJECTED) {
            return -1;
        }
        if (reason == DisconnectReason.ALIAS_IN_USE && aliasRetries++ >= 3) {
            return -1;
        }
        return nextDelayMillis();
    }

    public long nextDelayMillis() {
        if (failures >= 6) {
            return -1;
        }
        return Math.min(30000, 1000L << failures++);
    }

    public void reset() {
        failures = 0;
        aliasRetries = 0;
        networkFailures = 0;
        capacityFailures = 0;
    }
}

package com.rsvc.client;

import com.google.gson.Gson;
import com.rsvc.VoiceObserver;
import com.rsvc.network.DisconnectReason;
import com.rsvc.network.VoiceConnection;
import com.rsvc.network.VoicePacket;
import com.rsvc.proximity.VoiceAlias;
import com.rsvc.proximity.VoiceIdentity;

import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.LongSupplier;
import java.util.function.LongUnaryOperator;

/**
 * Voice-session ownership, recovery and game-presence policy, independent of RuneLite and Swing.
 * Commands run on the owning thread. Transport callbacks run on the calling network thread;
 * the adapter must dispatch them back before applying session changes. Volatile snapshots are
 * safe for audio callbacks. This class creates no threads, timers or blocking work.
 */
public final class VoiceClient {
    public enum GameState { LOGGED_IN, TRANSITION, LOGGED_OUT }
    public enum TickAction { NONE, JOIN, RECONNECT, WAIT_FOR_LOGIN }
    public enum GameUpdate { UNCHANGED, LOGGED_OUT, POSITION_UNAVAILABLE }

    public interface Listener {
        void status(VoiceConnection source, String message);
        void roster(VoiceConnection source, List<VoiceConnection.Peer> peers);
        void audio(VoiceConnection source, VoicePacket packet);
        void ended(VoiceConnection source, DisconnectReason reason);
        void room(VoiceConnection source, VoiceConnection.RoomState state);
    }

    private final LongSupplier nanoTime;
    private final LongUnaryOperator jitterMillis;
    private final ReconnectPolicy reconnect = new ReconnectPolicy();
    private final GameVoiceSession game = new GameVoiceSession();
    private volatile VoiceConnection connection;
    private volatile boolean eligible, partySelected;
    private volatile long eligibleAt;
    private volatile String room = "";
    private boolean wanted, recoveryPaused;
    private long retryAt;
    private String alias = "";
    private String character = "", identitySalt = "", identityToken = "";
    private int world;

    public VoiceClient() {
        this(System::nanoTime, bound -> ThreadLocalRandom.current().nextLong(bound));
    }

    VoiceClient(LongSupplier nanoTime, LongUnaryOperator jitterMillis) {
        this.nanoTime = nanoTime;
        this.jitterMillis = jitterMillis;
    }

    /**
     * Retries wait a random extra amount below this. A relay restart drops every client at once;
     * spreading the first retry over two seconds instead of half of one keeps the handshakes from
     * landing together. Later retries spread over their own backoff step, up to five seconds.
     */
    static long jitterBoundMillis(long delay) {
        return Math.max(2000, Math.min(delay, 5000));
    }

    public VoiceConnection connection() { return connection; }
    public boolean owns(VoiceConnection source) { return source != null && connection == source; }
    public boolean connectionWanted() { return wanted; }
    public boolean retryPending() { return retryAt != 0; }
    public String alias() { return alias; }
    public String roomCode() { return room; }
    public boolean recoveryPaused() { return recoveryPaused; }
    public boolean partySelected() { return partySelected; }
    public boolean eligible() { return eligible; }

    public boolean audioAllowed() {
        return eligible && nanoTime.getAsLong() - eligibleAt < 2_500_000_000L;
    }

    public void requestConnection() { wanted = true; }
    public void cancelConnectionRequest() { wanted = false; }
    public void newIdentity() { alias = VoiceAlias.create(); }

    /** Prepare callbacks and room gates before the adapter starts audio and opens the socket. */
    public VoiceConnection open(Gson gson, VoiceObserver observer, Listener listener) {
        if (connection != null) {
            throw new IllegalStateException("Voice connection already exists");
        }
        retryAt = 0;
        VoiceConnection[] owner = new VoiceConnection[1];
        VoiceConnection next = new VoiceConnection(gson, alias,
                message -> listener.status(owner[0], message),
                peers -> listener.roster(owner[0], peers),
                packet -> listener.audio(owner[0], packet),
                reason -> listener.ended(owner[0], reason), observer);
        owner[0] = next;
        next.roomListener(state -> {
            if (!owns(next)) {
                return;
            }
            // Close the gate on the network thread, before queued UI/session updates.
            if (partySelected && (!"updated".equals(state.reason) || !room.equals(state.code))) {
                next.requireRoom("");
            }
            listener.room(next, state);
        }, partySelected ? "" : room, !partySelected && recoveryPaused);
        next.requireRoom(partySelected ? "" : null);
        connection = next;
        return next;
    }

    /** Null means an obsolete connection callback. Negative delay means no further retry. */
    public Long disconnected(VoiceConnection source, DisconnectReason reason) {
        if (!owns(source)) {
            return null;
        }
        if (!partySelected) {
            recoveryPaused = source.roomRecoveryPaused();
            if (!source.recoveryRoomCode().isEmpty()) {
                room = source.recoveryRoomCode();
            }
        }
        connection = null;
        if (partySelected) {
            room = "";
        }
        invalidateAudio();
        long delay = reconnect.nextDelayMillis(reason);
        if (delay < 0) {
            wanted = false;
            alias = "";
        } else {
            if (reason == DisconnectReason.ALIAS_IN_USE) {
                alias = VoiceAlias.replacement(alias);
            }
            long jitter = jitterMillis.applyAsLong(jitterBoundMillis(delay));
            retryAt = nanoTime.getAsLong() + (delay + jitter) * 1_000_000;
        }
        return delay;
    }

    public void disconnect() {
        wanted = false;
        VoiceConnection previous = connection;
        connection = null;
        if (previous != null) {
            previous.close();
        }
        invalidateAudio();
        alias = room = character = identitySalt = identityToken = "";
        recoveryPaused = partySelected = false;
        world = 0;
        retryAt = 0;
        reconnect.reset();
    }

    public TickAction tick(GameState state, boolean enabled) {
        game.state(state);
        if (enabled && wanted && connection == null && retryAt == 0
                && state == GameState.LOGGED_IN) {
            return TickAction.JOIN;
        }
        if (retryAt != 0) {
            if (!enabled || game.ended()) {
                return TickAction.WAIT_FOR_LOGIN;
            }
            if (state == GameState.LOGGED_IN && nanoTime.getAsLong() >= retryAt) {
                return TickAction.RECONNECT;
            }
        }
        return TickAction.NONE;
    }

    public boolean acceptRoom(VoiceConnection source, VoiceConnection.RoomState state) {
        if (!owns(source)) {
            return false;
        }
        recoveryPaused = state.restorationFailed || source.roomRecoveryPaused();
        room = recoveryPaused ? source.recoveryRoomCode() : state.code;
        return true;
    }

    public void requestRoom(String action, String code) {
        if (connection != null) {
            connection.room(action, code);
            recoveryPaused = connection.roomRecoveryPaused();
        }
    }

    public boolean recoverRoom(boolean retry) {
        VoiceConnection current = connection;
        if (partySelected || current == null
                || !(retry ? current.retryRoomRecovery() : current.returnToNearbyVoice())) {
            return false;
        }
        recoveryPaused = false;
        if (!retry) {
            room = "";
        }
        return true;
    }

    public void selectParty() {
        partySelected = true;
        recoveryPaused = false;
    }

    public void stopParty() { partySelected = false; }

    public void position(String salt, String name, int world, Set<Long> nearby) {
        position(salt, name, world, nearby, Collections.emptySet());
    }

    public void position(String salt, String name, int world, Set<Long> nearby, Set<String> seen) {
        VoiceConnection current = connection;
        if (current == null) {
            return;
        }
        String token = VoiceIdentity.token(salt, name, world);
        String worldKey = VoiceIdentity.worldKey(salt, world);
        character = name;
        this.world = world;
        identitySalt = salt;
        identityToken = token;
        eligible = true;
        eligibleAt = nanoTime.getAsLong();
        game.positionUpdated(eligibleAt);
        current.proximity(salt, token, nearby, worldKey, seen);
    }

    public GameUpdate gameState(GameState state, boolean playerAvailable) {
        game.state(state);
        if (game.ended()) {
            return connection != null || retryAt != 0 ? GameUpdate.LOGGED_OUT : GameUpdate.UNCHANGED;
        }
        VoiceConnection current = connection;
        if (current == null || (game.hasFreshPosition(nanoTime.getAsLong()) && playerAvailable)) {
            return GameUpdate.UNCHANGED;
        }
        String salt = current.matchingSalt();
        if (!salt.isEmpty() && !character.isEmpty() && !salt.equals(identitySalt)) {
            identityToken = VoiceIdentity.token(salt, character, world);
            identitySalt = salt;
        }
        eligible = current.suspendProximity(identitySalt, identityToken);
        eligibleAt = eligible ? nanoTime.getAsLong() : 0;
        return GameUpdate.POSITION_UNAVAILABLE;
    }

    public void invalidateAudio() {
        game.invalidatePosition();
        eligible = false;
    }

    public void pause() {
        invalidateAudio();
        eligibleAt = 0;
        if (connection != null) {
            connection.proximity(connection.matchingSalt(), "", Collections.emptySet());
        }
    }

    public void heartbeat(boolean muted, boolean deaf) {
        VoiceConnection current = connection;
        if (current != null) {
            current.selfStatus(muted, deaf);
            current.heartbeat();
            current.checkHealth();
            if (current.isStable()) {
                reconnect.reset();
            }
        }
    }
}

