            }

            /* Scale and convert to linear scale */
            gain_Q16[k] = Inlines.silk_log2lin(Inlines.silk_min_32(Inlines.silk_SMULWB(INV_SCALE_Q16, prev_ind.Val) + OFFSET, 3967));
            /* 3967 = 31 in Q7 */
