package com.rsvc.codec;

package com.rsvc.network;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

/** Strict reads of relay control fields; anything malformed is a protocol violation. */
final class ControlJson {
    private ControlJson() {}

    static long number(JsonObject object, String key, long min, long max) {
        return number(object.get(key), min, max);
    }

    /** An integral JSON number in [min, max]; fractions, strings and overflow are rejected. */
    static long number(JsonElement value, long min, long max) {
        if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber()) {
            throw new IllegalArgumentException();
        }
        long n = value.getAsBigDecimal().longValueExact();
        if (n < min || n > max) {
            throw new IllegalArgumentException();
        }
        return n;
    }
}

package com.rsvc.network;

/** Relay close categories; ordinary protocol rejection must never trigger an automatic retry. */
public enum DisconnectReason {
    NETWORK,
    SERVER_FULL,
    ALIAS_IN_USE,
    IDENTITY_IN_USE,
    REJECTED;

    public static DisconnectReason fromClose(int code) {
        if (code == 4013) {
            return SERVER_FULL;
        }
        if (code == 4009) {
            return ALIAS_IN_USE;
        }
        if (code == 4010) {
            return IDENTITY_IN_USE;
        }
        return code == 1008 ? REJECTED : NETWORK;
    }

    public static DisconnectReason fromHttp(int code, String relayError) {
        if (code == 503 && "server_full".equals(relayError)) {
            return SERVER_FULL;
        }
        return code >= 500 || code == 429 ? NETWORK : REJECTED;
    }
}

package com.rsvc.network;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;

/**
 * Peers the relay introduced to this client: matched nearby (each can see the other) or sharing
 * its invite room. There is no downloadable list of other players.
 */
final class PeerIntroductions {
    // A memory bound against a hostile relay: 255 mutual sightings plus room members.
    static final int MAX_ENTRIES = 512;
    private Map<Long, String> members = new HashMap<>();
    private Map<String, Long> identities = Collections.emptyMap();

    Map<String, Long> identities() {
        return identities;
    }

    /** Applies one {type:"matches", add:[{id,token}], remove:[id]} change; all or nothing. */
    void accept(JsonObject message) {
        JsonArray add = message.getAsJsonArray("add"), remove = message.getAsJsonArray("remove");
        if (add == null || remove == null || add.size() + remove.size() > MAX_ENTRIES) {
            throw new IllegalArgumentException();
        }
        Map<Long, String> next = new HashMap<>(members);
        for (JsonElement entry : remove) {
            if (next.remove(ControlJson.number(entry, 1, 0xffffffffL)) == null) {
                throw new IllegalArgumentException();
            }
        }
        for (JsonElement entry : add) {
            JsonObject item = entry.getAsJsonObject();
            long id = ControlJson.number(item, "id", 1, 0xffffffffL);
            JsonElement value = item.get("token");
            if (value == null
                    || !value.isJsonPrimitive()
                    || !value.getAsJsonPrimitive().isString()
                    || !value.getAsString().matches("[0-9a-f]{64}")) {
                throw new IllegalArgumentException();
            }
            next.put(id, value.getAsString());
        }
        if (next.size() > MAX_ENTRIES || new HashSet<>(next.values()).size() != next.size()) {
            throw new IllegalArgumentException();
        }
        Map<String, Long> index = new HashMap<>();
        next.forEach((id, token) -> index.put(token, id));
        members = next;
        identities = Collections.unmodifiableMap(index);
    }
}

package com.rsvc.network;

import java.io.IOException;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetSocketAddress;
import java.net.SocketTimeoutException;
import java.nio.ByteBuffer;
import java.security.GeneralSecurityException;
import java.util.Arrays;

import javax.crypto.Cipher;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;

/**
 * Optional encrypted UDP audio path to the relay ("UDP audio" in the relay's PROTOCOL.md). The
 * WebSocket stays the control channel and the audio fallback. Sends are serialized on this
 * object; one daemon thread receives and calls the listener.
 */
final class UdpAudio implements AutoCloseable {
    static final int PROBE = 1, AUDIO_UP = 2, PROBE_ACK = 3, AUDIO_DOWN = 4;
    // Client to relay: kind, session, 64-bit counter. Relay to client: kind, 32-bit counter.
    static final int HEADER = 17, DOWN_HEADER = 5, TAG = 16;
    static final int TO_RELAY = 0, FROM_RELAY = 1;

    interface Listener {
        void acknowledged();

        void audio(byte[] payload);
    }

    private final DatagramSocket socket;
    private final byte[] session;
    private final SecretKeySpec key;
    private final Cipher sealer, opener;
    private final Listener listener;
    private long sent;
    // Owned by the receive thread.
    private long received;
    private volatile boolean closed;

    UdpAudio(InetSocketAddress relay, byte[] session, byte[] key, Listener listener)
            throws IOException, GeneralSecurityException {
        this.session = session.clone();
        this.key = new SecretKeySpec(key, "AES");
        this.listener = listener;
        sealer = Cipher.getInstance("AES/GCM/NoPadding");
        opener = Cipher.getInstance("AES/GCM/NoPadding");
        socket = new DatagramSocket();
        // A connected socket only accepts datagrams from the relay's address.
        socket.connect(relay);
        socket.setSoTimeout(1000);
        Thread reader = new Thread(this::receive, "RS VC UDP");
        reader.setDaemon(true);
        reader.start();
    }

    synchronized boolean send(int kind, byte[] payload) {
        if (closed) {
            return false;
        }
        try {
            byte[] datagram = seal(sealer, key, kind, session, ++sent, payload);
            socket.send(new DatagramPacket(datagram, datagram.length));
            return true;
        } catch (IOException | GeneralSecurityException e) {
            return false;
        }
    }

    private void receive() {
        byte[] buffer = new byte[2048];
        DatagramPacket packet = new DatagramPacket(buffer, buffer.length);
        while (!closed) {
            try {
                packet.setLength(buffer.length);
                socket.receive(packet);
            } catch (SocketTimeoutException e) {
                continue;
            } catch (IOException e) {
                if (closed) {
                    return;
                }
                continue;
            }
            int length = packet.getLength();
            int kind = buffer[0] & 0xff;
            if (length < DOWN_HEADER + TAG || (kind != PROBE_ACK && kind != AUDIO_DOWN)) {
                continue;
            }
            long counter = Integer.toUnsignedLong(ByteBuffer.wrap(buffer, 1, 4).getInt());
            // Replayed and reordered datagrams are dropped; late audio is useless.
            if (counter <= received) {
                continue;
            }
            byte[] payload = open(opener, key, buffer, length);
            if (payload == null) {
                continue;
            }
            received = counter;
            if (kind == PROBE_ACK) {
                if (payload.length == 0) {
                    listener.acknowledged();
                }
            } else {
                listener.audio(payload);
            }
        }
    }

    @Override
    public void close() {
        closed = true;
        socket.close();
    }

    private static byte[] header(int kind, byte[] session, long counter) {
        return ByteBuffer.allocate(HEADER).put((byte) kind).put(session).putLong(counter).array();
    }

    static GCMParameterSpec nonce(int direction, long counter) {
        return new GCMParameterSpec(
                TAG * 8, ByteBuffer.allocate(12).putInt(direction).putLong(counter).array());
    }

    /** A client-to-relay datagram. */
    static byte[] seal(
            Cipher cipher, SecretKeySpec key, int kind, byte[] session, long counter, byte[] payload)
            throws GeneralSecurityException {
        byte[] header = header(kind, session, counter);
        cipher.init(Cipher.ENCRYPT_MODE, key, nonce(TO_RELAY, counter));
        cipher.updateAAD(header);
        byte[] sealed = cipher.doFinal(payload);
        byte[] datagram = Arrays.copyOf(header, HEADER + sealed.length);
        System.arraycopy(sealed, 0, datagram, HEADER, sealed.length);
        return datagram;
    }

    /**
     * The payload of a relay-to-client datagram, or null when it fails authentication. The
     * connected socket already identifies the session, so the header carries no session ID.
     */
    static byte[] open(Cipher cipher, SecretKeySpec key, byte[] data, int length) {
        if (length < DOWN_HEADER + TAG) {
            return null;
        }
        try {
            cipher.init(
                    Cipher.DECRYPT_MODE,
                    key,
                    nonce(FROM_RELAY, Integer.toUnsignedLong(ByteBuffer.wrap(data, 1, 4).getInt())));
            cipher.updateAAD(data, 0, DOWN_HEADER);
            return cipher.doFinal(data, DOWN_HEADER, length - DOWN_HEADER);
        } catch (GeneralSecurityException e) {
            return null;
        }
    }
}

