/**
 * WebSocket protocol and routing state. Synchronized entry points serialize OkHttp callbacks with
 * game/audio-thread calls; volatile snapshots support read-only access without taking the monitor.
 * Callbacks run on the invoking thread and must dispatch game/UI work to the appropriate thread.
 */
public final class VoiceConnection extends WebSocketListener implements AutoCloseable {
    private static final Logger log = LoggerFactory.getLogger(VoiceConnection.class);
    public static final class Peer {
        public final long id;
        public final String name;
        public final boolean muted, deaf;

        public Peer(long id, String name) {
            this(id, name, false, false);
        }

        public Peer(long id, String name, boolean muted, boolean deaf) {
            this.id = id;
            this.name = name;
            this.muted = muted;
            this.deaf = deaf;
        }
    }

    private final Gson gson;
    private final Consumer<String> status;
    private final Consumer<List<Peer>> roster;
    private final Consumer<VoicePacket> receiver;
    private final Consumer<DisconnectReason> ended;
    private final String name;
    private volatile VoiceObserver observer;
    private long heartbeatSentAt;
    private volatile long heartbeatAckAt;
    private volatile boolean active;
    private boolean proximitySuspended;
    private String lastState = "";
    // What the relay holds for near and seen, so states can carry only the changes. A new
    // connection starts empty on both sides; a key change resends both lists in full,
    // because the relay drops states it receives under the old key.
    private Set<Long> sentNear = Collections.emptySet();
    private Set<String> sentSeen = Collections.emptySet();
    private boolean resendLists = true;
    private String token = "";
    private volatile String salt = "";
    public static final int MAX_SEEN = 255;
    // Introduced peers by matching token; replaced whole on each change.
    private volatile Map<String, Long> introduced = Collections.emptyMap();
    private final PeerIntroductions introductions = new PeerIntroductions();
    private int protocol;
    private volatile int frameMillis = 20;
    private long keyEpoch;
    private boolean refreshingKey;
    private boolean roomPending;
    private String world = "";
    private boolean selfMuted, selfDeaf;
    private boolean peerStatusDirty = true;
    private String lastPeerStatus = "";
    private long peerStatusSentAt;
    private volatile String roomCode = "";
    private String resumeRoom = "";
    private String restoringRoom = "";
    private String recoveryRoom = "";
    private boolean failedRoomRecovery;
    private String requiredRoom;
    private Consumer<RoomState> roomListener = state -> {};

    private Set<Long> nearby = Collections.emptySet();
    // Fingerprints of visible characters (first five hex digits of their tokens), for mutual
    // discovery. Full tokens of other players never leave the client.
    private Set<String> seen = Collections.emptySet();
    private long revision;
    private long acknowledgedRevision = -1;
    private volatile long selfId;
    private int listeners;
    private volatile WebSocket socket;
    private volatile boolean open;
    private volatile boolean closed;
    private volatile boolean deaf;
    private volatile long activityAt;
    private volatile long openedAt;
    private volatile List<Peer> peers = Collections.emptyList();
    private volatile Set<Long> blocked = Collections.emptySet();
    private Set<String> mutedAliases = Collections.emptySet();

    // Optional UDP audio path; the WebSocket stays the control channel and audio fallback.
    static final long UDP_PROBE_INTERVAL = 250_000_000L, UDP_PROBE_WINDOW = 2_500_000_000L;
    static final long UDP_KEEPALIVE = 5_000_000_000L, UDP_TIMEOUT = 12_000_000_000L;
    static final long UDP_RETRY = 30_000_000_000L;
    private URI endpoint;
    private boolean udpWanted;
    private UdpAudio udp;
    private volatile boolean udpActive;
    // System.nanoTime() values; 0 means unset.
    private long udpProbeUntil, udpProbedAt, udpAckAt, udpRetryAt;

    public static final class RoomState {
        public final String code, reason;
        public final boolean restorationFailed;

        RoomState(String code, String reason, boolean restorationFailed) {
            this.code = code;
            this.reason = reason;
            this.restorationFailed = restorationFailed;
        }
    }

    public synchronized void roomListener(Consumer<RoomState> listener, String resume) {
        roomListener(listener, resume, false);
    }

    public synchronized void roomListener(Consumer<RoomState> listener, String resume, boolean paused) {
        roomListener = listener;
        recoveryRoom = resume;
        failedRoomRecovery = paused && !resume.isEmpty();
        resumeRoom = failedRoomRecovery ? "" : resume;
        restoringRoom = resumeRoom;
    }

    public boolean inRoom() {
        return !roomCode.isEmpty();
    }

    public String roomCode() {
        return roomCode;
    }

    /** Null is ordinary voice; empty blocks all audio while party discovery is in progress. */
    public synchronized void requireRoom(String code) {
        requiredRoom = code;
        sendState();
    }

    private boolean scopeAllowed() {
        return restoringRoom.isEmpty()
                && !failedRoomRecovery
                && (requiredRoom == null
                        || (!requiredRoom.isEmpty() && requiredRoom.equals(roomCode)));
    }

    public synchronized boolean roomRecoveryPaused() {
        return failedRoomRecovery;
    }

    public synchronized boolean awaitingRoomRecovery() {
        return failedRoomRecovery || !restoringRoom.isEmpty();
    }

    /** Kept in memory only, including across a failed retry. */
    public synchronized String recoveryRoomCode() {
        return recoveryRoom;
    }

    public synchronized boolean retryRoomRecovery() {
        if (!failedRoomRecovery || recoveryRoom.isEmpty() || !roomsAvailable()) {
            return false;
        }
        restoringRoom = recoveryRoom;
        failedRoomRecovery = false;
        requestRoom("join", recoveryRoom, true);
        return true;
    }

    public synchronized boolean returnToNearbyVoice() {
        if (!failedRoomRecovery || roomPending || !roomCode.isEmpty()) {
            return false;
        }
        recoveryRoom = "";
        failedRoomRecovery = false;
        sendState();
        return true;
    }

    public synchronized boolean roomsAvailable() {
        return protocol != 0 && activeConnection() && !roomPending;
    }

    public synchronized void room(String action, String code) {
        requestRoom(action, code, false);
    }

    private void requestRoom(String action, String code, boolean automatic) {
        if (!roomsAvailable()) {
            if (!automatic) {
                status.accept("Voice isn't connected yet — try the room again");
            }
            return;
        }
        if (!action.equals("create") && !action.equals("join") && !action.equals("leave")) {
            throw new IllegalArgumentException();
        }
        String normalized =
                code.replace("-", "").replace(" ", "").toLowerCase(java.util.Locale.ROOT);
        if (action.equals("join") && !normalized.matches("[0-9a-f]{24}")) {
            status.accept("Enter a valid 24-character invite code");
            return;
        }
        JsonObject msg = new JsonObject();
        msg.addProperty("type", "room");
        msg.addProperty("action", action);
        if (action.equals("join")) {
            msg.addProperty("code", normalized);
        }
        roomPending = true;
        if (!automatic) {
            resumeRoom = "";
            restoringRoom = "";
            recoveryRoom = "";
            failedRoomRecovery = false;
        }
        listeners = 0;
        peers = Collections.emptyList();
        roster.accept(peers);
        sendState();
        send(msg);
    }

    public VoiceConnection(
            Gson gson,
            String name,
            Consumer<String> status,
            Consumer<List<Peer>> roster,
            Consumer<VoicePacket> receiver,
            Consumer<DisconnectReason> ended) {
        this(gson, name, status, roster, receiver, ended, VoiceObserver.NONE);
    }

    public VoiceConnection(
            Gson gson,
            String name,
            Consumer<String> status,
            Consumer<List<Peer>> roster,
            Consumer<VoicePacket> receiver,
            Consumer<DisconnectReason> ended,
            VoiceObserver observer) {
        if (!VoiceAlias.valid(name)) {
            throw new IllegalArgumentException("Use a generated voice alias");
        }
        this.gson = gson;
        this.name = name;
        this.status = status;
        this.roster = roster;
        this.receiver = receiver;
        this.ended = ended;
        this.observer = observer;
    }

    public synchronized void observer(VoiceObserver next) {
        if (observer != next) {
            observer = next;
            observer.connected(open && !closed);
        }
    }

    public boolean isOpen() {
        return open && !closed;
    }

    public static URI validateEndpoint(String endpoint) {
        URI uri = URI.create(endpoint);
        String host = uri.getHost();
        boolean local =
                "127.0.0.1".equals(host)
                        || "[::1]".equals(host)
                        || "::1".equals(host)
                        || "localhost".equals(host);
        if (host == null
                || uri.getRawUserInfo() != null
                || uri.getRawQuery() != null
                || uri.getRawFragment() != null
                || !("wss".equals(uri.getScheme()) || (local && "ws".equals(uri.getScheme())))
                || !"/v1/voice".equals(uri.getPath())) {
            throw new IllegalArgumentException(
                    "Use wss://host/v1/voice (ws:// allowed only on loopback)");
        }
        return uri;
    }

    /**
     * Audio moves to UDP on its own when the relay offers it and the relay is reached without a
     * proxy, and returns to the WebSocket whenever UDP stops answering.
     */
    public void connect(OkHttpClient client, String endpoint) {
        connect(client, endpoint, true);
    }

    /** With udp false, audio always stays on the WebSocket. */
    public void connect(OkHttpClient client, String endpoint, boolean udp) {
        URI uri = validateEndpoint(endpoint);
        udpEndpoint(uri, udp && direct(client, uri));
        socket = client.newWebSocket(new Request.Builder().url(endpoint).build(), this);
    }

    synchronized void udpEndpoint(URI uri, boolean wanted) {
        endpoint = uri;
        udpWanted = wanted;
    }

    /** UDP would bypass RuneLite's proxy, so it is used only when the relay is reached directly. */
    static boolean direct(OkHttpClient client, URI endpoint) {
        try {
            Proxy proxy = client.proxy();
            if (proxy != null) {
                return proxy.type() == Proxy.Type.DIRECT;
            }
            int port = endpoint.getPort() != -1 ? endpoint.getPort() : 443;
            for (String scheme : new String[] {"https", "socket"}) {
                URI target = new URI(scheme, null, endpoint.getHost(), port, null, null, null);
                for (Proxy selected : client.proxySelector().select(target)) {
                    if (selected.type() != Proxy.Type.DIRECT) {
                        return false;
                    }
                }
            }
            return true;
        } catch (RuntimeException | URISyntaxException e) {
            return false;
        }
    }

    /** True while audio is sent and received over UDP rather than the WebSocket. */
    public boolean usingUdp() {
        return udpActive;
    }

    private void offerUdp(JsonObject offer) {
        long port = ControlJson.number(offer, "port", 1, 65535);
        String session = offer.get("session").getAsString(), key = offer.get("key").getAsString();
        if (!session.matches("[0-9a-f]{16}") || !key.matches("[0-9a-f]{32}")) {
            throw new IllegalArgumentException();
        }
        if (!udpWanted || endpoint == null || udp != null) {
            return;
        }
        try {
            String host = endpoint.getHost().replace("[", "").replace("]", "");
            udp = new UdpAudio(
                    new InetSocketAddress(InetAddress.getByName(host), (int) port),
                    hex(session),
                    hex(key),
                    new UdpAudio.Listener() {
                        @Override
                        public void acknowledged() {
                            udpAcknowledged(System.nanoTime());
                        }

                        @Override
                        public void audio(byte[] payload) {
                            observer.message(false, true, payload.length);
                            receiveAudio(payload);
                        }
                    });
            udpProbeUntil = System.nanoTime() + UDP_PROBE_WINDOW;
        } catch (java.io.IOException | java.security.GeneralSecurityException e) {
            log.debug("RSVC UDP unavailable: {}", e.getClass().getSimpleName());
        }
    }

    private static byte[] hex(String text) {
        byte[] bytes = new byte[text.length() / 2];
        for (int i = 0; i < bytes.length; i++) {
            bytes[i] = (byte) Integer.parseInt(text.substring(2 * i, 2 * i + 2), 16);
        }
        return bytes;
    }

    /** Probes until the relay answers, keeps the path alive, and falls back when it stops. */
    synchronized void udpTick(long now) {
        if (udp == null || closed) {
            return;
        }
        if (udpActive) {
            if (now - udpAckAt > UDP_TIMEOUT) {
                log.debug("RSVC UDP audio stopped; using the WebSocket");
                udpActive = false;
                udpRetryAt = now + UDP_RETRY;
                sendTransport(false);
            } else if (now - udpProbedAt >= UDP_KEEPALIVE) {
                probe(now);
            }
            return;
        }
        if (udpProbeUntil == 0 && udpRetryAt != 0 && now - udpRetryAt >= 0) {
            udpProbeUntil = now + UDP_PROBE_WINDOW;
            udpRetryAt = 0;
        }
        if (udpProbeUntil == 0) {
            return;
        }
        if (now - udpProbeUntil > 0) {
            udpProbeUntil = 0;
            udpRetryAt = now + UDP_RETRY;
        } else if (udpProbedAt == 0 || now - udpProbedAt >= UDP_PROBE_INTERVAL) {
            probe(now);
        }
    }

    private void probe(long now) {
        udpProbedAt = now;
        udp.send(UdpAudio.PROBE, new byte[0]);
    }

    synchronized void udpAcknowledged(long now) {
        if (closed || udp == null) {
            return;
        }
        udpAckAt = now;
        if (!udpActive) {
            log.debug("RSVC UDP audio path confirmed");
            udpActive = true;
            udpProbeUntil = 0;
            udpRetryAt = 0;
            sendTransport(true);
        }
    }

    private void sendTransport(boolean useUdp) {
        sendText("{\"type\":\"transport\",\"udp\":" + useUdp + "}");
    }

    @Override
    public synchronized void onOpen(WebSocket webSocket, Response response) {
        if (closed) {
            webSocket.cancel();
            return;
        }
        socket = webSocket;
        open = true;
        observer.connected(true);
        openedAt = heartbeatAckAt = System.nanoTime();
        status.accept("Connected — finding nearby voices");
    }

    @Override
    public synchronized void onMessage(WebSocket webSocket, String text) {
        if (closed) {
            return;
        }
        if (observer != VoiceObserver.NONE) {
            observer.message(
                    false, false, text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length);
        }
        if (text.length() > 65536) {
            fail("Relay sent oversized control data", false);
            return;
        }
        try {
            JsonObject msg = gson.fromJson(text, JsonObject.class);
            String type = msg.get("type").getAsString();
            if ("welcome".equals(type)) {
                int version = (int) ControlJson.number(msg, "v", 9, 9);
                String key = msg.get("salt").getAsString();
                if (!key.matches("[0-9a-f]{64}") || !salt.isEmpty()) {
                    throw new IllegalArgumentException();
                }
                keyEpoch = ControlJson.number(msg, "keyEpoch", 1, 9007199254740991L);
                selfId = ControlJson.number(msg, "id", 1, 0xffffffffL);
                long frame = ControlJson.number(msg, "frameMs", 20, 40);
                if (frame != 20 && frame != 40) {
                    throw new IllegalArgumentException();
                }
                frameMillis = (int) frame;
                protocol = version;
                salt = key;
                JsonObject hello = new JsonObject();
                hello.addProperty("type", "hello");
                hello.addProperty("v", protocol);
                hello.addProperty("alias", name);
                send(hello);
                if (msg.has("udp")) {
                    offerUdp(msg.getAsJsonObject("udp"));
                }
                return;
            }
            if (protocol == 0) {
                throw new IllegalArgumentException();
            }
            if ("matching_key".equals(type)) {
                long epoch =
                        ControlJson.number(msg, "keyEpoch", keyEpoch + 1, 9007199254740991L);
                String key = msg.get("salt").getAsString();
                if (!key.matches("[0-9a-f]{64}") || key.equals(salt)) {
                    throw new IllegalArgumentException();
                }
                keyEpoch = epoch;
                refreshingKey = true;
                resendLists = true;
                salt = key;
                // Existing routing/audio stays valid; only fresh local matching may send state.
                return;
            }
            if ("room".equals(type)) {
                String code = msg.get("code").getAsString(),
                        reason = msg.get("reason").getAsString();
                if ((!code.isEmpty() && !code.matches("[0-9a-f]{24}"))
                        || !java.util.Arrays.asList(
                                        "created",
                                        "joined",
                                        "left",
                                        "updated",
                                        "full",
                                        "unavailable")
                                .contains(reason)) {
                    throw new IllegalArgumentException();
                }
                String previousRoom = roomCode;
                boolean changed = !previousRoom.equals(code);
                roomCode = code;
                if (changed) {
                    listeners = 0;
                    peers = Collections.emptyList();
                    acknowledgedRevision = -1;
                    roster.accept(peers);
                }
                boolean restorationFailed = false;
                if (!restoringRoom.isEmpty() && !"updated".equals(reason)) {
                    restorationFailed = !"joined".equals(reason) || !restoringRoom.equals(code);
                    failedRoomRecovery = restorationFailed;
                    restoringRoom = "";
                    if (!restorationFailed) {
                        recoveryRoom = "";
                    }
                }
                roomListener.accept(new RoomState(code, reason, restorationFailed));
                if (!"updated".equals(reason)) {
                    roomPending = false;
                }
                sendState();
                return;
            }
            if ("heartbeat".equals(type)) {
                heartbeatAckAt = System.nanoTime();
                return;
            }
            if ("transport".equals(type)) {
                JsonElement value = msg.get("udp");
                if (udp == null || value == null || !value.isJsonPrimitive()
                        || !value.getAsJsonPrimitive().isBoolean()) {
                    throw new IllegalArgumentException();
                }
                // The relay refused or dropped UDP: keep audio on the WebSocket and retry later.
                if (!value.getAsBoolean() && udpActive) {
                    udpActive = false;
                    udpRetryAt = System.nanoTime() + UDP_RETRY;
                }
                return;
            }
            if ("matches".equals(type)) {
                introductions.accept(msg);
                introduced = introductions.identities();
                return;
            }
            if (!"peers".equals(type)) {
                throw new IllegalArgumentException();
            }
            String scope = msg.has("scope") ? msg.get("scope").getAsString() : "";
            if (roomPending || !scope.equals(roomCode)) {
                return;
            }
            if (msg.get("rev").getAsLong() != revision) {
                return;
            }
            int audience = msg.get("listeners").getAsInt();
            JsonArray array = msg.getAsJsonArray("peers");
            // Rosters only name peers this client was introduced to.
            if (array.size() > PeerIntroductions.MAX_ENTRIES
                    || audience < 0
                    || audience > array.size()) {
                throw new IllegalArgumentException();
            }
            List<Peer> next = new ArrayList<>();
            Set<Long> peerIds = new HashSet<>();
            for (JsonElement item : array) {
                JsonObject p = item.getAsJsonObject();
                long id = p.get("id").getAsLong();
                String n = p.get("alias").getAsString();
                if (id < 1 || id > 0xffffffffL || !VoiceAlias.valid(n) || !peerIds.add(id)) {
                    throw new IllegalArgumentException();
                }
                if (inRoom() || nearby.contains(id)) {
                    next.add(new Peer(id, n, optionalBoolean(p, "muted"), optionalBoolean(p, "deaf")));
                }
            }
            acknowledgedRevision = revision;
            listeners = audience;
            peers = Collections.unmodifiableList(next);
            roster.accept(peers);
        } catch (RuntimeException e) {
            fail("Relay sent invalid control data", false);
        }
    }

    @Override
    public synchronized void onMessage(WebSocket webSocket, ByteString bytes) {
        if (closed) {
            return;
        }
        observer.message(false, true, bytes.size());
        receiveAudio(bytes.toByteArray());
    }

    private synchronized void receiveAudio(byte[] bytes) {
        if (closed) {
            return;
        }
        if (!canReceive()) {
            return;
        }
        try {
            VoicePacket packet = VoicePacket.downstream(bytes);
            for (Peer peer : peers) {
                if (peer.id == packet.speaker
                        && (inRoom() || nearby.contains(peer.id))
                        && !blocked.contains(peer.id)
                        && !mutedAliases.contains(peer.name)) {
                    receiver.accept(packet);
                    return;
                }
            }
        } catch (IllegalArgumentException ignored) {
            /* Malformed audio never reaches the decoder. */
        }
    }

    private boolean activeConnection() {
        return open
                && !closed
                && active
                && activityAt != 0
                && System.nanoTime() - activityAt < 2_500_000_000L;
    }

    private boolean canReceive() {
        return activeConnection()
                && (!proximitySuspended || inRoom())
                && !deaf && !roomPending && scopeAllowed();
    }

    public synchronized boolean canTransmit() {
        return canReceive()
                && acknowledgedRevision == revision
                && listeners > 0
                && (inRoom() || !nearby.isEmpty())
                && !peers.isEmpty();
    }

    public String matchingSalt() {
        return salt;
    }

    /** This connection's relay ID from welcome, or 0 before it arrives. */
    public long selfId() {
        return selfId;
    }

    /** True once the relay has acknowledged the latest state (registration accepted). */
    public synchronized boolean stateAcknowledged() {
        return revision > 0 && acknowledgedRevision == revision;
    }

    /** Opus packet duration the relay asked for in welcome: 20 (default) or 40 ms. */
    public int frameMillis() {
        return frameMillis;
    }

    /** Relay IDs of introduced peers, keyed by their matching tokens. */
    public Map<String, Long> introductions() {
        return introduced;
    }

    public synchronized void mutedAliases(Set<String> aliases) {
        mutedAliases = new HashSet<>(aliases);
    }

    public boolean isStable() {
        return open && !closed && System.nanoTime() - openedAt > 30_000_000_000L;
    }

    public void checkHealth() {
        if (open && !closed && System.nanoTime() - heartbeatAckAt > 15_000_000_000L) {
            fail("Relay stopped responding");
        }
    }

    /** Called only with locally matched consenting voice IDs, never arbitrary player hashes. */
    public synchronized void proximity(String matchingKey, String identity, Set<Long> ids) {
        proximity(matchingKey, identity, ids, "", Collections.emptySet());
    }

    public synchronized void proximity(
            String matchingKey,
            String identity,
            Set<Long> ids,
            String worldKey,
            Set<String> fingerprints) {
        if (!matchingKey.equals(salt)) {
            return; // A key update raced local matching; retry with the new key next tick.
        }
        refreshingKey = false;
        if (!identity.isEmpty() && !identity.matches("[0-9a-f]{64}")) {
            throw new IllegalArgumentException("Invalid voice token");
        }
        if (!worldKey.isEmpty() && !worldKey.matches("[0-9a-f]{64}")) {
            throw new IllegalArgumentException("Invalid world key");
        }
        if (ids.size() > MAX_SEEN) {
            throw new IllegalArgumentException("Too many nearby peers");
        }
        if (fingerprints.size() > MAX_SEEN
                || !fingerprints.stream().allMatch(f -> f.matches("[0-9a-f]{5}"))) {
            throw new IllegalArgumentException("Invalid sightings");
        }
        token = identity;
        proximitySuspended = false;
        world = identity.isEmpty() ? "" : worldKey;
        active = !identity.isEmpty();
        activityAt = System.nanoTime();
        nearby = active ? new HashSet<>(ids) : Collections.emptySet();
        seen = active ? new java.util.TreeSet<>(fingerprints) : Collections.emptySet();
        List<Peer> retained = new ArrayList<>();
        for (Peer peer : peers) {
            if (inRoom() || nearby.contains(peer.id)) {
                retained.add(peer);
            }
        }
        if (retained.size() != peers.size()) {
            peers = Collections.unmodifiableList(retained);
            roster.accept(peers);
        }
        sendState();
        if (!resumeRoom.isEmpty() && roomsAvailable()) {
            String code = resumeRoom;
            resumeRoom = "";
            requestRoom("join", code, true);
        }
    }

    /** Keep established room audio alive without claiming an old map position is current. */
    public synchronized boolean suspendProximity(String matchingKey, String identity) {
        boolean changed = !proximitySuspended || !world.isEmpty() || !nearby.isEmpty();
        // The client may refresh its established identity without reading a loading scene.
        // Never publish an old token under a new matching-key epoch.
        if (matchingKey.equals(salt)) {
            if (!identity.equals(token) && !identity.isEmpty()
                    && !identity.matches("[0-9a-f]{64}")) {
                throw new IllegalArgumentException("Invalid voice token");
            }
            changed |= !identity.equals(token) || refreshingKey;
            token = identity;
            refreshingKey = false;
        }
        proximitySuspended = true;
        world = "";
        nearby = Collections.emptySet();
        seen = Collections.emptySet();
        active = inRoom() && !token.isEmpty();
        activityAt = System.nanoTime();
        if (!inRoom() && !peers.isEmpty()) {
            peers = Collections.emptyList();
            roster.accept(peers);
        }
        if (changed) {
            sendState();
        }
        return activeConnection() && inRoom() && !roomPending && scopeAllowed();
    }

    public synchronized void heartbeat() {
        if (!activeConnection() && active) {
            proximity(salt, "", Collections.emptySet());
        }
        long now = System.nanoTime();
        udpTick(now);
        sendPeerStatus(now);
        if (salt.isEmpty() || (heartbeatSentAt != 0 && now - heartbeatSentAt < 5_000_000_000L)) {
            return;
        }
        if (sendText("{\"type\":\"heartbeat\"}")) {
            heartbeatSentAt = now;
        }
    }

    /** Latest self-selected controls only; transmission is coalesced by heartbeat(). */
    public synchronized void selfStatus(boolean muted, boolean deaf) {
        peerStatusDirty |= selfMuted != muted || selfDeaf != deaf;
        selfMuted = muted;
        selfDeaf = deaf;
    }

    void sendPeerStatus(long now) {
        if (!peerStatusDirty || (peerStatusSentAt != 0 && now - peerStatusSentAt < 5_000_000_000L)) {
            return;
        }
        String message = "{\"type\":\"status\",\"muted\":" + selfMuted + ",\"deaf\":" + selfDeaf + "}";
        if (message.equals(lastPeerStatus)) {
            peerStatusDirty = false;
        } else if (sendText(message)) {
            lastPeerStatus = message;
            peerStatusSentAt = now;
            peerStatusDirty = false;
        }
    }

    private static boolean optionalBoolean(JsonObject object, String key) {
        if (!object.has(key)) {
            return false;
        }
        JsonElement value = object.get(key);
        if (!value.isJsonPrimitive() || !value.getAsJsonPrimitive().isBoolean()) {
            throw new IllegalArgumentException("Invalid status flag");
        }
        return value.getAsBoolean();
    }

    public synchronized void transmit(byte[] packet) {
        WebSocket current = socket;
        if (!canTransmit() || current == null) {
            return;
        }
        if (udpActive && udp.send(UdpAudio.AUDIO_UP, packet)) {
            observer.message(true, true, packet.length);
            return;
        }
        // Skip new audio during temporary TCP congestion instead of building more
        // delay or tearing down a healthy control/room connection. Heartbeat
        // health checks still close a connection that actually stops responding.
        if (current.queueSize() > 2048) {
            return;
        }
        if (!current.send(ByteString.of(packet))) {
            fail("Voice send failed");
        } else {
            observer.message(true, true, packet.length);
        }
    }

    public synchronized void listening(boolean deaf, Set<Long> blocked) {
        this.deaf = deaf;
        this.blocked = new HashSet<>(blocked);
        sendState();
    }

    private void sendState() {
        if (salt.isEmpty() || refreshingKey) {
            return;
        }
        JsonObject msg = new JsonObject();
        msg.addProperty("type", "state");
        msg.addProperty("token", proximitySuspended && !inRoom() ? "" : token);
        boolean exclusive = requiredRoom != null || !restoringRoom.isEmpty() || failedRoomRecovery;
        msg.addProperty("world", exclusive ? "" : world);
        msg.addProperty("keyEpoch", keyEpoch);
        msg.addProperty("deaf", deaf || !scopeAllowed());
        JsonArray list = new JsonArray();
        for (long id : new java.util.TreeSet<>(blocked)) {
            list.add(id);
        }
        msg.add("blocked", list);
        Set<Long> near = exclusive ? Collections.emptySet() : new java.util.TreeSet<>(nearby);
        Set<String> sightings =
                !exclusive && !world.isEmpty()
                        ? new java.util.TreeSet<>(seen)
                        : Collections.emptySet();
        String text = gson.toJson(msg);
        boolean full = resendLists;
        if (!full && text.equals(lastState) && near.equals(sentNear) && sightings.equals(sentSeen)) {
            return;
        }
        listChange(msg, "near", near, full ? null : sentNear, JsonArray::add);
        listChange(msg, "seen", sightings, full ? null : sentSeen, null);
        msg.addProperty("rev", revision + 1);
        if (sendText(gson.toJson(msg))) {
            revision++;
            lastState = text;
            sentNear = near;
            sentSeen = sightings;
            resendLists = false;
        }
    }

    /**
     * Adds one set to a state: the full list, or nameAdd/nameRemove when that is smaller, or
     * nothing when it is unchanged. Fingerprints (adder null) are concatenated hex strings.
     */
    private static <T> void listChange(
            JsonObject msg,
            String name,
            Set<T> next,
            Set<T> previous,
            java.util.function.BiConsumer<JsonArray, T> adder) {
        if (previous != null && next.equals(previous)) {
            return;
        }
        List<T> added = new ArrayList<>(), removed = new ArrayList<>();
        if (previous != null) {
            for (T item : next) {
                if (!previous.contains(item)) {
                    added.add(item);
                }
            }
            for (T item : previous) {
                if (!next.contains(item)) {
                    removed.add(item);
                }
            }
        }
        if (previous == null || added.size() + removed.size() >= next.size()) {
            msg.add(name, encode(new ArrayList<>(next), adder));
            return;
        }
        if (!added.isEmpty()) {
            msg.add(name + "Add", encode(added, adder));
        }
        if (!removed.isEmpty()) {
            msg.add(name + "Remove", encode(removed, adder));
        }
    }

    private static <T> JsonElement encode(
            List<T> items, java.util.function.BiConsumer<JsonArray, T> adder) {
        if (adder == null) {
            StringBuilder text = new StringBuilder();
            new java.util.TreeSet<>(items).forEach(text::append);
            return new com.google.gson.JsonPrimitive(text.toString());
        }
        JsonArray array = new JsonArray();
        for (T item : items) {
            adder.accept(array, item);
        }
        return array;
    }

    private void send(JsonObject msg) {
        sendText(gson.toJson(msg));
    }

    private boolean sendText(String text) {
        WebSocket current = socket;
        if (!open || closed || current == null || !current.send(text)) {
            return false;
        }
        if (observer != VoiceObserver.NONE) {
            observer.message(
                    true, false, text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length);
        }
        return true;
    }

    @Override
    public void onClosing(WebSocket webSocket, int code, String reason) {
        log.debug(
                "RSVC relay closing: code={}, category={}",
                code,
                DisconnectReason.fromClose(code));
        webSocket.close(code, null);
        DisconnectReason category = DisconnectReason.fromClose(code);
        fail(
                category == DisconnectReason.SERVER_FULL
                        ? "Voice server full"
                        : "Relay disconnected (" + code + ")",
                category);
    }

    @Override
    public void onFailure(WebSocket webSocket, Throwable t, Response response) {
        // Exception messages and server-provided close text may contain sensitive data.
        log.debug(
                "RSVC transport failure: exception={}, cause={}, http={}",
                t.getClass().getSimpleName(),
                t.getCause() == null ? "none" : t.getCause().getClass().getSimpleName(),
                response == null ? 0 : response.code());
        DisconnectReason category =
                response == null
                        ? DisconnectReason.NETWORK
                        : DisconnectReason.fromHttp(
                                response.code(), response.header("X-RSVC-Error"));
        fail(
                category == DisconnectReason.SERVER_FULL
                        ? "Voice server full"
                        : response == null
                                ? "Connection failed — check relay URL/network"
                                : "Relay refused connection (HTTP " + response.code() + ")",
                category);
    }

    @Override
    public void onClosed(WebSocket webSocket, int code, String reason) {
        log.debug(
                "RSVC relay closed: code={}, category={}",
                code,
                DisconnectReason.fromClose(code));
        DisconnectReason category = DisconnectReason.fromClose(code);
        fail(
                category == DisconnectReason.SERVER_FULL ? "Voice server full" : "Disconnected",
                category);
    }

    private void fail(String message) {
        fail(message, true);
    }

    private void fail(String message, boolean retry) {
        fail(message, retry ? DisconnectReason.NETWORK : DisconnectReason.REJECTED);
    }

    private synchronized void fail(String message, DisconnectReason reason) {
        if (closed) {
            return;
        }
        log.debug(
                "RSVC disconnect: category={}, detail={}, active={}, room={}, pending={},"
                        + " scopeAllowed={}, revision={}, acknowledged={}, peers={}, listeners={}",
                reason, message, activeConnection(), inRoom(), roomPending, scopeAllowed(),
                revision, acknowledgedRevision, peers.size(), listeners);
        close();
        status.accept(message);
        ended.accept(reason);
    }

    @Override
    public synchronized void close() {
        if (closed) {
            return;
        }
        closed = true;
        open = false;
        active = false;
        activityAt = 0;
        udpActive = false;
        if (udp != null) {
            udp.close();
        }
        observer.connected(false);
        WebSocket current = socket;
        if (current != null) {
            current.cancel();
        }
    }
}

package com.rsvc.network;

import java.nio.ByteBuffer;
import java.util.Arrays;

/**
 * Mono, 48 kHz Opus packets. Senders use 20 ms; receivers also play 40 ms. Sequences count 20 ms
 * frames, including omitted ones, and a packet carries its first frame's number. Integers use
 * network byte order.
 */
public final class VoicePacket {
    public static final int MAX_OPUS = 400;
    public final long speaker;
    public final long sequence;
    public final byte[] opus;

    private VoicePacket(long speaker, long sequence, byte[] opus) {
        this.speaker = speaker;
        this.sequence = sequence;
        this.opus = opus;
    }

    public static byte[] upstream(long sequence, byte[] opus) {
        if (opus.length == 0 || opus.length > MAX_OPUS) {
            throw new IllegalArgumentException("Invalid Opus length");
        }
        return ByteBuffer.allocate(5 + opus.length)
                .put((byte) 1)
                .putInt((int) sequence)
                .put(opus)
                .array();
    }

    /** Relay to client: speaker ID, sequence, then the speaker's Opus bytes. */
    public static VoicePacket downstream(byte[] bytes) {
        if (bytes.length < 9 || bytes.length > MAX_OPUS + 8) {
            throw new IllegalArgumentException("Invalid voice packet");
        }
        ByteBuffer buf = ByteBuffer.wrap(bytes);
        long speaker = Integer.toUnsignedLong(buf.getInt());
        long sequence = Integer.toUnsignedLong(buf.getInt());
        if (speaker == 0) {
            throw new IllegalArgumentException("Invalid speaker");
        }
        return new VoicePacket(speaker, sequence, Arrays.copyOfRange(bytes, 8, bytes.length));
    }
}

package com.rsvc.party;

/**
 * A Join party voice click made before RuneLite has synced the local party member, or before the
 * relay is ready for rooms. RuneLite reports the party a moment before its own member record, so
 * the click waits briefly instead of being dropped. Client thread only.
 */
public final class PartyJoinRequest {
    public enum Step {
        NONE,
        WAIT,
        START,
        EXPIRED
    }

    static final long WAIT_MS = 15_000;
    private long until;

    public void request(long now) {
        until = now + WAIT_MS;
    }

    public void cancel() {
        until = 0;
    }

    public boolean pending() {
        return until != 0;
    }

    /** Called each tick; START and EXPIRED end the request. */
    public Step step(boolean ready, long now) {
        if (until == 0) {
            return Step.NONE;
        }
        if (ready) {
            until = 0;
            return Step.START;
        }
        if (now >= until) {
            until = 0;
            return Step.EXPIRED;
        }
        return Step.WAIT;
    }
}

package com.rsvc.party;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * Client-thread room discovery. No server changes, party secrets at the relay, or audio over Party.
 */
public final class PartyVoice {
    private static final long DISCOVERY_MS = 2_000;
    private static final long ADVERTISEMENT_MS = 5_000;
    private static final long STALE_MS = 20_000;
    private final Map<Long, Offer> offers = new HashMap<>();
    private final Map<String, Long> rejected = new HashMap<>();
    private long partyId;
    private long memberId;
    private boolean localRelay;
    private boolean active;
    private String confirmed = "";
    private Command pending;
    private long discoverAt;
    private long advertiseAt;

    public static final class Command {
        public final String action;
        public final String code;

        private Command(String action, String code) {
            this.action = action;
            this.code = code;
        }
    }

    private static final class Offer {
        private final String room;
        private final long at;

        private Offer(String room, long at) {
            this.room = room;
            this.at = at;
        }
    }

    public void start(long party, long member, boolean local, long now) {
        stop();
        active = true;
        partyId = party;
        memberId = member;
        localRelay = local;
        discoverAt = now + DISCOVERY_MS;
    }

    public void stop() {
        active = false;
        confirmed = "";
        pending = null;
        offers.clear();
        rejected.clear();
        advertiseAt = Long.MIN_VALUE;
    }

    public boolean active() {
        return active;
    }

    public boolean sameParty(long id) {
        return active && partyId == id;
    }

    public RsVcPartyVoice message() {
        return new RsVcPartyVoice(partyId, localRelay, active, confirmed);
    }

    public boolean advertisementDue(long now) {
        if (!active || now < advertiseAt) {
            return false;
        }
        advertiseAt = now + ADVERTISEMENT_MS;
        return true;
    }

    public void requestAdvertisement() {
        advertiseAt = Long.MIN_VALUE;
    }

    /** Caller validates the sender against the current RuneLite party membership. */
    public void receive(RsVcPartyVoice message, long now) {
        if (!active || !message.matches(partyId, localRelay) || message.getMemberId() == memberId) {
            return;
        }
        if (!message.participating()) {
            offers.remove(message.getMemberId());
            return;
        }
        Offer previous = offers.put(message.getMemberId(), new Offer(message.room(), now));
        if (previous == null) {
            requestAdvertisement();
        }
    }

    public void retainMembers(Set<Long> members, long now) {
        offers.entrySet()
                .removeIf(e -> !members.contains(e.getKey()) || now - e.getValue().at > STALE_MS);
        rejected.entrySet().removeIf(e -> now >= e.getValue());
    }

    private String target() {
        // Concurrent creators converge on one room without a permanent leader. Anyone still
        // connected can advertise it after its creator leaves the party.
        String target = confirmed;
        for (Offer offer : offers.values()) {
            if (!offer.room.isEmpty()
                    && !rejected.containsKey(offer.room)
                    && (target.isEmpty() || offer.room.compareTo(target) < 0)) {
                target = offer.room;
            }
        }
        return target;
    }

    /** Null permits ordinary voice; empty blocks all audio until a party room is confirmed. */
    public String requiredRoom() {
        if (!active) {
            return null;
        }
        return pending == null && confirmed.equals(target()) ? confirmed : "";
    }

    public Command nextCommand(String currentRoom, long now) {
        if (!active || pending != null) {
            return null;
        }
        String target = target();
        if (!target.isEmpty()) {
            if (!target.equals(currentRoom)) {
                pending = new Command("join", target);
            } else {
                confirmed = target;
            }
        } else if (!currentRoom.isEmpty()) {
            // The relay's create command keeps an existing room, so leave private voice first.
            pending = new Command("leave", "");
        } else if (now >= discoverAt) {
            pending = new Command("create", "");
        }
        return pending;
    }

    public void roomChanged(String code, String reason, long now) {
        if (!active || "updated".equals(reason)) {
            return;
        }
        if ("full".equals(reason)) {
            stop();
            return;
        }
        if ("unavailable".equals(reason)) {
            String failed =
                    pending != null && "join".equals(pending.action) ? pending.code : confirmed;
            if (!failed.isEmpty()) {
                // Bounded by currently advertised rooms; never retain arbitrary remote history.
                if (rejected.size() >= 128) {
                    rejected.clear();
                }
                rejected.put(failed, now + STALE_MS);
                offers.entrySet().removeIf(e -> failed.equals(e.getValue().room));
            }
            if (failed.equals(confirmed)) {
                confirmed = "";
            }
            discoverAt = now + DISCOVERY_MS;
        } else if (pending != null) {
            if (("create".equals(pending.action) && "created".equals(reason))
                    || ("join".equals(pending.action)
                            && "joined".equals(reason)
                            && pending.code.equals(code))) {
                confirmed = code;
            } else if ("leave".equals(pending.action) && "left".equals(reason)) {
                confirmed = "";
            }
        }
        pending = null;
        requestAdvertisement();
    }

    public void reconnect() {
        pending = null;
        requestAdvertisement();
    }
}

package com.rsvc.party;

import net.runelite.client.party.messages.PartyMemberMessage;

/** Small control message carried by RuneLite; audio and party passphrases never go here. */
public final class RsVcPartyVoice extends PartyMemberMessage {
    private int version = 1;
    private long partyId;
    private boolean localRelay;
    private boolean participating;
    private String room = "";

    public RsVcPartyVoice() {}

    public RsVcPartyVoice(long partyId, boolean localRelay, boolean participating, String room) {
        this.partyId = partyId;
        this.localRelay = localRelay;
        this.participating = participating;
        this.room = room;
    }

    public boolean matches(long party, boolean local) {
        return version == 1
                && partyId == party
                && localRelay == local
                && room != null
                && (room.isEmpty() || room.matches("[0-9a-f]{24}"));
    }

    public boolean participating() {
        return participating;
    }

    public String room() {
        return room;
    }
}

package com.rsvc.proximity;

import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

/**
 * Client-thread matching. Unregistered players' full tokens are never returned or uploaded; only
 * a 20-bit fingerprint of each visible name leaves the client, shared by many possible names.
 */
public final class ProximityMatcher {
    public static final int RANGE = 20;
    private final Map<String, String> cache = new HashMap<>();
    private String salt = "";
    private int world;

    public static boolean inRange(
            int localX, int localY, int localPlane, int x, int y, int plane, boolean sameScene) {
        return sameScene
                && localPlane == plane
                && Math.max(Math.abs(localX - x), Math.abs(localY - y)) <= RANGE;
    }

    public Set<Long> match(
            String nextSalt, int nextWorld, Set<String> nearbyNames, Map<String, Long> registered) {
        return new HashSet<>(matchNames(nextSalt, nextWorld, nearbyNames, registered).values());
    }

    /** Names in this map stay local; only matched IDs are used for network proximity. */
    public Map<String, Long> matchNames(
            String nextSalt,
            int nextWorld,
            Set<String> visibleNames,
            Map<String, Long> registered) {
        use(nextSalt, nextWorld);
        Map<String, Long> ids = new HashMap<>();
        if (salt.isEmpty() || registered.isEmpty()) {
            return ids;
        }
        for (String name : visibleNames) {
            String token = token(name);
            Long id = token == null ? null : registered.get(token);
            if (id != null) {
                ids.put(name, id);
            }
        }
        return ids;
    }

    /** Fingerprints of up to {@code limit} names, in the given (nearest-first) order. */
    public Set<String> fingerprints(String nextSalt, int nextWorld, List<String> names, int limit) {
        use(nextSalt, nextWorld);
        Set<String> result = new TreeSet<>();
        if (salt.isEmpty()) {
            return result;
        }
        for (String name : names) {
            if (result.size() >= limit) {
                break;
            }
            String token = token(name);
            if (token != null) {
                result.add(token.substring(0, FINGERPRINT_DIGITS));
            }
        }
        return result;
    }

    public static final int FINGERPRINT_DIGITS = 5;

    private void use(String nextSalt, int nextWorld) {
        if (!salt.equals(nextSalt) || world != nextWorld) {
            clear();
            salt = nextSalt;
            world = nextWorld;
        }
    }

    private String token(String name) {
        try {
            String normalized = VoiceIdentity.normalize(name);
            if (cache.size() >= 2048 && !cache.containsKey(normalized)) {
                cache.clear();
            }
            return cache.computeIfAbsent(normalized, n -> VoiceIdentity.token(salt, n, world));
        } catch (IllegalArgumentException ignored) {
            return null; // An incomplete player name cannot be matched.
        }
    }

    public void clear() {
        cache.clear();
        salt = "";
        world = 0;
    }
}

package com.rsvc.proximity;

import java.security.SecureRandom;

/** Random per-join label, with no input from the RuneScape account or character. */
public final class VoiceAlias {
    private static final SecureRandom RANDOM = new SecureRandom();

    private VoiceAlias() {}

    public static String create() {
        return String.format(java.util.Locale.ROOT, "VC-%08x", RANDOM.nextInt());
    }

    public static boolean valid(String alias) {
        return alias != null && alias.matches("VC-[0-9a-f]{8}");
    }

    public static String replacement(String previous) {
        String next;
        do {
            next = create();
        } while (next.equals(previous));
        return next;
    }
}

package com.rsvc.proximity;

import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.util.Locale;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

/**
 * Matching only: names and worlds never leave this helper in plaintext. Not account authentication.
 */
public final class VoiceIdentity {
    private VoiceIdentity() {}

    public static String normalize(String name) {
        return name.replace('\u00a0', ' ').replace('_', ' ').trim().toLowerCase(Locale.ROOT);
    }

    public static String token(String salt, String name, int world) {
        if (salt == null
                || !salt.matches("[0-9a-f]{64}")
                || name == null
                || world < 1
                || world > 65535) {
            throw new IllegalArgumentException("Invalid matching context");
        }
        String normalized = normalize(name);
        if (!normalized.matches("[a-z0-9 -]{1,12}")) {
            throw new IllegalArgumentException("Character name unavailable");
        }
        return digest(salt, "rs-vc-4\n" + world + "\n" + normalized);
    }

    /**
     * Opaque world key for nearby discovery, not encryption: the relay can enumerate worlds. It
     * carries no map location, so region borders never separate nearby players.
     */
    public static String worldKey(String salt, int world) {
        if (salt == null || !salt.matches("[0-9a-f]{64}") || world < 1 || world > 65535) {
            throw new IllegalArgumentException("Invalid proximity context");
        }
        return digest(salt, "rs-vc-world-1\n" + world);
    }

    private static String digest(String salt, String context) {
        byte[] key = new byte[32];
        for (int i = 0; i < key.length; i++) {
            key[i] = (byte) Integer.parseInt(salt.substring(i * 2, i * 2 + 2), 16);
        }
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(key, "HmacSHA256"));
            byte[] digest = mac.doFinal(context.getBytes(StandardCharsets.UTF_8));
            StringBuilder result = new StringBuilder(64);
            for (byte b : digest) {
                result.append(Character.forDigit((b >>> 4) & 15, 16))
                        .append(Character.forDigit(b & 15, 16));
            }
            return result.toString();
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("Voice matching unavailable", e);
        }
    }
}

package com.rsvc.ui;

import com.rsvc.audio.AudioEngine;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dialog;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.BiConsumer;

import javax.swing.BorderFactory;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;

/**
 * Enumerates Java Sound devices off the UI/client threads; preserves existing exact-name settings.
 */
public final class AudioDevicePicker implements AutoCloseable {
    static final class Choice {
        final String value;
        private final boolean available;

        Choice(String value, boolean available) {
            this.value = value;
            this.available = available;
        }

        @Override
        public String toString() {
            return value.isEmpty() ? "Default" : value + (available ? "" : " (unavailable)");
        }
    }

    private final BiConsumer<String, String> save;
    private final ExecutorService scanner =
            Executors.newSingleThreadExecutor(
                    r -> {
                        Thread thread = new Thread(r, "RS VC audio device list");
                        thread.setDaemon(true);
                        return thread;
                    });
    private volatile boolean closed;
    private JDialog dialog; // EDT only.

    public AudioDevicePicker(BiConsumer<String, String> save) {
        this.save = save;
    }

    static DefaultComboBoxModel<Choice> choices(List<String> devices, String selected) {
        DefaultComboBoxModel<Choice> model = new DefaultComboBoxModel<>();
        model.addElement(new Choice("", true));
        for (String name : new LinkedHashSet<>(devices)) {
            if (!name.isEmpty()) {
                model.addElement(new Choice(name, true));
            }
        }
        if (!selected.isEmpty() && !devices.contains(selected)) {
            model.addElement(new Choice(selected, false));
        }
        for (int i = 0; i < model.getSize(); i++) {
            if (model.getElementAt(i).value.equals(selected)) {
                model.setSelectedItem(model.getElementAt(i));
            }
        }
        return model;
    }

    public void show(Component parent, String microphone, String speakers) {
        if (closed) {
            return;
        }
        if (dialog != null) {
            dialog.toFront();
            return;
        }
        JDialog window =
                new JDialog(
                        SwingUtilities.getWindowAncestor(parent),
                        "Audio devices",
                        Dialog.ModalityType.MODELESS);
        dialog = window;
        window.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
        JComboBox<Choice> mic =
                new JComboBox<>(choices(java.util.Collections.emptyList(), microphone));
        JComboBox<Choice> output =
                new JComboBox<>(choices(java.util.Collections.emptyList(), speakers));
        mic.setPreferredSize(new Dimension(360, 26));
        output.setPreferredSize(new Dimension(360, 26));
        JLabel status =
                new JLabel("Default follows your operating system. Apply keeps your voice room.");
        JButton refresh = new JButton("Refresh"),
                apply = new JButton("Apply"),
                cancel = new JButton("Cancel");
        JPanel fields = new JPanel(new GridLayout(4, 1, 0, 4));
        fields.add(new JLabel("Microphone"));
        fields.add(mic);
        fields.add(new JLabel("Speakers"));
        fields.add(output);
        JPanel actions = new JPanel(new GridLayout(1, 3, 4, 0));
        actions.add(refresh);
        actions.add(apply);
        actions.add(cancel);
        JPanel content = new JPanel(new BorderLayout(0, 8));
        content.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        content.add(status, BorderLayout.NORTH);
        content.add(fields, BorderLayout.CENTER);
        content.add(actions, BorderLayout.SOUTH);
        Runnable scan =
                () -> {
                    String selectedMic = ((Choice) mic.getSelectedItem()).value,
                            selectedOutput = ((Choice) output.getSelectedItem()).value;
                    mic.setEnabled(false);
                    output.setEnabled(false);
                    apply.setEnabled(false);
                    refresh.setEnabled(false);
                    status.setText("Looking for audio devices…");
                    try {
                        scanner.execute(
                                () -> {
                                    try {
                                        List<String> inputs = AudioEngine.devices(true),
                                                outputs = AudioEngine.devices(false);
                                        SwingUtilities.invokeLater(
                                                () -> {
                                                    if (closed || dialog != window) {
                                                        return;
                                                    }
                                                    mic.setModel(choices(inputs, selectedMic));
                                                    output.setModel(
                                                            choices(outputs, selectedOutput));
                                                    mic.setEnabled(true);
                                                    output.setEnabled(true);
                                                    apply.setEnabled(true);
                                                    refresh.setEnabled(true);
                                                    status.setText(
                                                            "Default follows your operating system."
                                                                    + " Apply keeps your voice room.");
                                                });
                                    } catch (RuntimeException unavailable) {
                                        SwingUtilities.invokeLater(
                                                () -> {
                                                    if (closed || dialog != window) {
                                                        return;
                                                    }
                                                    refresh.setEnabled(true);
                                                    status.setText(
                                                            "Could not list devices. Check audio"
                                                                    + " settings, then Refresh.");
                                                });
                                    }
                                });
                    } catch (java.util.concurrent.RejectedExecutionException stopped) {
                        window.dispose();
                    }
                };
        refresh.addActionListener(e -> scan.run());
        apply.addActionListener(
                e -> {
                    if (!closed) {
                        save.accept(
                                ((Choice) mic.getSelectedItem()).value,
                                ((Choice) output.getSelectedItem()).value);
                    }
                    window.dispose();
                });
        cancel.addActionListener(e -> window.dispose());
        window.addWindowListener(
                new WindowAdapter() {
                    @Override
                    public void windowClosed(WindowEvent event) {
                        if (dialog == window) {
                            dialog = null;
                        }
                    }
                });
        window.setContentPane(content);
        window.pack();
        window.setLocationRelativeTo(parent);
        scan.run();
        window.setVisible(true);
    }

    @Override
    public void close() {
        closed = true;
        scanner.shutdownNow();
        SwingUtilities.invokeLater(
                () -> {
                    if (dialog != null) {
                        dialog.dispose();
                    }
                });
    }
}

package com.rsvc.ui;

import java.awt.Component;
import java.awt.Window;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;

import javax.swing.SwingUtilities;
import javax.swing.Timer;

/** Voice activation follows the RuneLite window, including its sidebar and owned dialogs. */
public final class CaptureFocus implements AutoCloseable {
    private final Component canvas;
    private Window owner;
    private final Runnable lostFocus;
    // Accessed only on the Swing event thread.
    private final Set<Window> windows = Collections.newSetFromMap(new IdentityHashMap<>());
    private final WindowAdapter listener =
            new WindowAdapter() {
                @Override
                public void windowGainedFocus(WindowEvent event) {
                    refreshLater();
                }

                @Override
                public void windowLostFocus(WindowEvent event) {
                    refreshLater();
                }

                @Override
                public void windowClosed(WindowEvent event) {
                    refreshLater();
                }
            };
    // Owned dialogs can appear while the owner is unfocused, without an owner focus event.
    private final Timer discovery = new Timer(250, event -> refresh());
    private volatile boolean active;
    private volatile boolean closed;

    /** Construct on the Swing event thread; the canvas may attach to its window later. */
    public CaptureFocus(Component canvas, Runnable lostFocus) {
        this.canvas = canvas;
        this.lostFocus = lostFocus;
        refresh();
        discovery.start();
    }

    private void refreshLater() {
        // Evaluate the destination after a focus transfer, including newly opened dialogs.
        SwingUtilities.invokeLater(this::refresh);
    }

    private void collect(Window window, Set<Window> next) {
        if (window == null) {
            return;
        }
        if (window == owner || window.isDisplayable()) {
            next.add(window);
        }
        for (Window child : window.getOwnedWindows()) {
            collect(child, next);
        }
    }

    private void refresh() {
        if (closed) {
            return;
        }
        owner = SwingUtilities.getWindowAncestor(canvas);
        Set<Window> nextWindows = Collections.newSetFromMap(new IdentityHashMap<>());
        collect(owner, nextWindows);
        windows.removeIf(
                window -> {
                    if (nextWindows.contains(window)) {
                        return false;
                    }
                    unlisten(window);
                    return true;
                });
        boolean next = false;
        for (Window window : nextWindows) {
            if (windows.add(window)) {
                window.addWindowFocusListener(listener);
                window.addWindowListener(listener);
            }
            next |= window.isFocused();
        }
        boolean previous = active;
        active = next;
        if (previous && !next) {
            lostFocus.run();
        }
    }

    public boolean isActive() {
        return !closed && active;
    }

    @Override
    public void close() {
        closed = true;
        active = false;
        if (SwingUtilities.isEventDispatchThread()) {
            detach();
        } else {
            SwingUtilities.invokeLater(this::detach);
        }
    }

    private void unlisten(Window window) {
        window.removeWindowFocusListener(listener);
        window.removeWindowListener(listener);
    }

    private void detach() {
        discovery.stop();
        windows.forEach(this::unlisten);
        windows.clear();
    }
}

package com.rsvc.ui;

import com.rsvc.audio.NoiseGate;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;

import javax.swing.JComponent;

/** Microphone level bar with a marker where voice activation opens. Painted on the EDT. */
final class MicLevelMeter extends JComponent {
    static final double MIN_DB = -70;
    static final double MAX_DB = 0;
    private static final Color TRACK = new Color(45, 45, 45);
    private static final Color OPEN = new Color(85, 200, 130);
    private static final Color CLOSED = new Color(120, 120, 120);
    private static final Color MARKER = new Color(240, 200, 90);
    private NoiseGate.Level level;

    MicLevelMeter() {
        setPreferredSize(new Dimension(0, 8));
    }

    void level(NoiseGate.Level value) {
        level = value;
        repaint();
    }

    NoiseGate.Level level() {
        return level;
    }

    static int position(double db, int width) {
        double fraction = (Math.max(MIN_DB, Math.min(MAX_DB, db)) - MIN_DB) / (MAX_DB - MIN_DB);
        return (int) Math.round(fraction * width);
    }

    @Override
    protected void paintComponent(Graphics g) {
        int width = getWidth(), height = getHeight();
        g.setColor(TRACK);
        g.fillRect(0, 0, width, height);
        NoiseGate.Level current = level;
        if (current == null) {
            return;
        }
        g.setColor(current.open ? OPEN : CLOSED);
        g.fillRect(0, 0, position(current.levelDb, width), height);
        if (!Double.isNaN(current.thresholdDb)) {
            int x = Math.min(width - 2, position(current.thresholdDb, width));
            g.setColor(MARKER);
            g.fillRect(x, 0, 2, height);
        }
    }

    /** One-line description beside the meter. */
    static String describe(NoiseGate.Level value) {
        if (value == null) {
            return "Mic idle";
        }
        String level = "Mic " + Math.round(Math.max(-99, value.levelDb)) + " dB";
        if (Double.isNaN(value.thresholdDb)) {
            return level;
        }
        return level + " · sends above " + Math.round(value.thresholdDb) + " dB";
    }
}

package com.rsvc.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;

import javax.swing.Icon;

/** Small cached vector icons for self-selected controls, independent of local peer mutes. */
final class PeerStatusIcon implements Icon {
    private static final Icon MIC = new PeerStatusIcon(true, false);
    private static final Icon DEAF = new PeerStatusIcon(false, true);
    private static final Icon BOTH = new PeerStatusIcon(true, true);
    private final boolean muted, deaf;

    static Icon of(boolean muted, boolean deaf) {
        return muted ? (deaf ? BOTH : MIC) : deaf ? DEAF : null;
    }

    private PeerStatusIcon(boolean muted, boolean deaf) {
        this.muted = muted;
        this.deaf = deaf;
    }

    public int getIconWidth() {
        return muted && deaf ? 30 : 14;
    }

    public int getIconHeight() {
        return 14;
    }

    public void paintIcon(Component c, Graphics graphics, int x, int y) {
        Graphics2D g = (Graphics2D) graphics.create();
        try {
            g.translate(x, y);
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            if (muted) {
                g.setColor(c.getForeground());
                g.drawRoundRect(5, 1, 4, 7, 3, 3);
                g.drawArc(3, 4, 8, 7, 180, 180);
                g.drawLine(7, 11, 7, 13);
                slash(g);
                if (deaf) {
                    g.translate(16, 0);
                }
            }
            if (deaf) {
                g.setColor(c.getForeground());
                g.drawArc(2, 2, 10, 10, 0, 180);
                g.drawRoundRect(2, 7, 3, 5, 2, 2);
                g.drawRoundRect(9, 7, 3, 5, 2, 2);
                slash(g);
            }
        } finally {
            g.dispose();
        }
    }

    private static void slash(Graphics2D g) {
        g.setColor(new Color(225, 120, 120));
        g.drawLine(1, 1, 13, 13);
    }
}

package com.rsvc.ui;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.function.Supplier;

/** Only projects a short cached list of active speakers; never scans or hashes the scene. */
public final class SpeakingOverlay extends Overlay {
    private static final BufferedImage ICON = createIcon();
    private final Client client;
    private final Supplier<List<Player>> speakers;

    public SpeakingOverlay(Client client, Supplier<List<Player>> speakers) {
        this.client = client;
        this.speakers = speakers;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        Player self = client.getLocalPlayer();
        if (client.getGameState() != GameState.LOGGED_IN || self == null) {
            return null;
        }
        for (Player player : speakers.get()) {
            if (player.getWorldView() != self.getWorldView()
                    || player.getWorldLocation().getPlane() != self.getWorldLocation().getPlane()) {
                continue;
            }
            Point point = player.getCanvasImageLocation(ICON, player.getLogicalHeight() + 28);
            if (point != null) {
                graphics.drawImage(ICON, point.getX(), point.getY(), null);
            }
        }
        return null;
    }

    static BufferedImage createIcon() {
        BufferedImage icon = new BufferedImage(20, 22, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = icon.createGraphics();
        try {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setColor(new Color(15, 35, 24, 230));
            g.fillRoundRect(0, 0, 20, 18, 7, 7);
            g.fillPolygon(new int[] {7, 13, 10}, new int[] {16, 16, 22}, 3);
            g.setColor(new Color(95, 245, 145));
            g.fillRoundRect(4, 6, 3, 6, 2, 2);
            g.fillRoundRect(9, 3, 3, 12, 2, 2);
            g.fillRoundRect(14, 5, 3, 8, 2, 2);
        } finally {
            g.dispose();
        }
        return icon;
    }
}

